import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-sklearn-cross-validation-with-linear-models":{"intro":"In this lab, we will be using cross-validation with linear models. We will be using the diabetes dataset and applying GridSearchCV to find the best alpha value for Lasso regression. We will then plot the errors and use LassoCV to see how much we can trust the selection of alpha.","steps":[{"title":"Load and prepare the dataset","body":["First, we will load and prepare the diabetes dataset. We will only use the first 150 samples for this exercise."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom sklearn import datasets\n\nX, y = datasets.load_diabetes(return_X_y=True)\nX = X[:150]\ny = y[:150]"}]},{"title":"Apply GridSearchCV","body":["Next, we will apply GridSearchCV to find the best alpha value for Lasso regression. We will use a range of alpha values from 10^-4 to 10^-0.5 with 30 values in between. We will use 5 folds for cross-validation."],"code":[{"lang":"python","text":"from sklearn.linear_model import Lasso\nfrom sklearn.model_selection import GridSearchCV\n\nlasso = Lasso(random_state=0, max_iter=10000)\nalphas = np.logspace(-4, -0.5, 30)\n\ntuned_parameters = [{\"alpha\": alphas}]\nn_folds = 5\n\nclf = GridSearchCV(lasso, tuned_parameters, cv=n_folds, refit=False)\nclf.fit(X, y)"}]},{"title":"Plot the errors","body":["We will now plot the errors to see the best alpha value. We will plot the mean test scores and the standard errors of the scores."],"code":[{"lang":"python","text":"scores = clf.cv_results_[\"mean_test_score\"]\nscores_std = clf.cv_results_[\"std_test_score\"]\n\nplt.figure().set_size_inches(8, 6)\nplt.semilogx(alphas, scores)\n\nstd_error = scores_std / np.sqrt(n_folds)\n\nplt.semilogx(alphas, scores + std_error, \"b--\")\nplt.semilogx(alphas, scores - std_error, \"b--\")\n\nplt.fill_between(alphas, scores + std_error, scores - std_error, alpha=0.2)\n\nplt.ylabel(\"CV score +/- std error\")\nplt.xlabel(\"alpha\")\nplt.axhline(np.max(scores), linestyle=\"--\", color=\".5\")\nplt.xlim([alphas[0], alphas[-1]])"}]},{"title":"Use LassoCV to check alpha selection","body":["Use LassoCV to check alpha selection","Finally, we will use LassoCV to see how much we can trust the selection of alpha. We will use KFold with 3 folds."],"code":[{"lang":"python","text":"from sklearn.linear_model import LassoCV\nfrom sklearn.model_selection import KFold\n\nlasso_cv = LassoCV(alphas=alphas, random_state=0, max_iter=10000)\nk_fold = KFold(3)\n\nprint(\"Answer to the bonus question:\", \"how much can you trust the selection of alpha?\")\nprint()\nprint(\"Alpha parameters maximising the generalization score on different\")\nprint(\"subsets of the data:\")\nfor k, (train, test) in enumerate(k_fold.split(X, y)):\n    lasso_cv.fit(X[train], y[train])\n    print(\n        \"[fold {0}] alpha: {1:.5f}, score: {2:.5f}\".format(\n            k, lasso_cv.alpha_, lasso_cv.score(X[test], y[test])\n        )\n    )\n\nprint()\nprint(\"Answer: Not very much since we obtained different alphas for different\")\nprint(\"subsets of the data and moreover, the scores for these alphas differ\")\nprint(\"quite substantially.\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.linear_model import LassoCV\nfrom sklearn.model_selection import KFold\n\nlasso_cv = LassoCV(alphas=alphas, random_state=0, max_iter=10000)\nk_fold = KFold(3)\n\nprint(\"Answer to the bonus question:\", \"how much can you trust the selection of alpha?\")\nprint()\nprint(\"Alpha parameters maximising the generalization score on different\")\nprint(\"subsets of the data:\")\nfor k, (train, test) in enumerate(k_fold.split(X, y)):\n    lasso_cv.fit(X[train], y[train])\n    print(\n        \"[fold {0}] alpha: {1:.5f}, score: {2:.5f}\".format(\n            k, lasso_cv.alpha_, lasso_cv.score(X[test], y[test])\n        )\n    )\n\nprint()\nprint(\"Answer: Not very much since we obtained different alphas for different\")\nprint(\"subsets of the data and moreover, the scores for these alphas differ\")\nprint(\"quite substantially.\")"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-cross-validation-on-digits-dataset":{"intro":"This lab uses cross-validation with a support vector machine (SVM) on the digits dataset. This is a classification problem, where the task is to identify digits from images of handwritten digits.","steps":[{"title":"Load the dataset","body":["First, we need to load the digits dataset from scikit-learn and split it into features and labels."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn import datasets\n\nX, y = datasets.load_digits(return_X_y=True)"}]},{"title":"Create a Support Vector Machine (SVM) model","body":["Create a Support Vector Machine (SVM) model","Next, we create an SVM model with a linear kernel."],"code":[{"lang":"python","text":"from sklearn import svm\n\nsvc = svm.SVC(kernel=\"linear\")"}]},{"title":"Define the hyperparameter values to test","body":["Define the hyperparameter values to test","We will test different values of the regularization parameter C, which controls the trade-off between maximizing the margin and minimizing the classification error. We will test 10 logarithmically-spaced values between 10^-10 and 1."],"code":[{"lang":"python","text":"C_s = np.logspace(-10, 0, 10)"}]},{"title":"Perform cross-validation and record results","body":["Perform cross-validation and record results","For each value of C, we perform 10-fold cross-validation and record the mean and standard deviation of the scores."],"code":[{"lang":"python","text":"from sklearn.model_selection import cross_val_score\n\nscores = list()\nscores_std = list()\nfor C in C_s:\n    svc.C = C\n    this_scores = cross_val_score(svc, X, y, n_jobs=1)\n    scores.append(np.mean(this_scores))\n    scores_std.append(np.std(this_scores))"}]},{"title":"Plot the results","body":["Finally, we plot the mean scores as a function of C, and also include error bars to visualize the standard deviation."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.figure()\nplt.semilogx(C_s, scores)\nplt.semilogx(C_s, np.array(scores) + np.array(scores_std), \"b--\")\nplt.semilogx(C_s, np.array(scores) - np.array(scores_std), \"b--\")\nlocs, labels = plt.yticks()\nplt.yticks(locs, list(map(lambda x: \"%g\" % x, locs)))\nplt.ylabel(\"CV score\")\nplt.xlabel(\"Parameter C\")\nplt.ylim(0, 1.1)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nplt.figure()\nplt.semilogx(C_s, scores)\nplt.semilogx(C_s, np.array(scores) + np.array(scores_std), \"b--\")\nplt.semilogx(C_s, np.array(scores) - np.array(scores_std), \"b--\")\nlocs, labels = plt.yticks()\nplt.yticks(locs, list(map(lambda x: \"%g\" % x, locs)))\nplt.ylabel(\"CV score\")\nplt.xlabel(\"Parameter C\")\nplt.ylim(0, 1.1)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-cross-validation-techniques-with-scikit-lear":{"intro":"Cross-validation is a technique for evaluating machine learning models by training several models on different subsets of the available data and evaluating them on the complementary subset. This helps to avoid overfitting and ensures that the model is generalizable. In this tutorial, we will use scikit-learn to explore different cross-validation techniques and their behavior.","steps":[{"title":"Visualize the Data","body":["In this step, we will visualize the data we will be working with. The data consists of 100 randomly generated input datapoints, 3 classes split unevenly across datapoints, and 10 \"groups\" split evenly across datapoints."],"code":[{"lang":"python","text":"# Generate the class/group data\nn_points = 100\nX = rng.randn(100, 10)\n\npercentiles_classes = [0.1, 0.3, 0.6]\ny = np.hstack([[ii] * int(100 * perc) for ii, perc in enumerate(percentiles_classes)])\n\n# Generate uneven groups\ngroup_prior = rng.dirichlet([2] * 10)\ngroups = np.repeat(np.arange(10), rng.multinomial(100, group_prior))\n\n\ndef visualize_groups(classes, groups, name):\n    # Visualize dataset groups\n    fig, ax = plt.subplots()\n    ax.scatter(\n        range(len(groups)),\n        [0.5] * len(groups),\n        c=groups,\n        marker=\"_\",\n        lw=50,\n        cmap=cmap_data,\n    )\n    ax.scatter(\n        range(len(groups)),\n        [3.5] * len(groups),\n        c=classes,\n        marker=\"_\",\n        lw=50,\n        cmap=cmap_data,\n    )\n    ax.set(\n        ylim=[-1, 5],\n        yticks=[0.5, 3.5],\n        yticklabels=[\"Data\\ngroup\", \"Data\\nclass\"],\n        xlabel=\"Sample index\",\n    )\n\n\nvisualize_groups(y, groups, \"no groups\")"}]},{"title":"Visualize Cross-Validation Indices","body":["Visualize Cross-Validation Indices","In this step, we will define a function to visualize the behavior of each cross-validation object. We will perform 4 splits of the data. On each split, we will visualize the indices chosen for the training set (in blue) and the test set (in red)."],"code":[{"lang":"python","text":"def plot_cv_indices(cv, X, y, group, ax, n_splits, lw=10):\n    \"\"\"Create a sample plot for indices of a cross-validation object.\"\"\"\n\n    # Generate the training/testing visualizations for each CV split\n    for ii, (tr, tt) in enumerate(cv.split(X=X, y=y, groups=group)):\n        # Fill in indices with the training/test groups\n        indices = np.array([np.nan] * len(X))\n        indices[tt] = 1\n        indices[tr] = 0\n\n        # Visualize the results\n        ax.scatter(\n            range(len(indices)),\n            [ii + 0.5] * len(indices),\n            c=indices,\n            marker=\"_\",\n            lw=lw,\n            cmap=cmap_cv,\n            vmin=-0.2,\n            vmax=1.2,\n        )\n\n    # Plot the data classes and groups at the end\n    ax.scatter(\n        range(len(X)), [ii + 1.5] * len(X), c=y, marker=\"_\", lw=lw, cmap=cmap_data\n    )\n\n    ax.scatter(\n        range(len(X)), [ii + 2.5] * len(X), c=group, marker=\"_\", lw=lw, cmap=cmap_data\n    )\n\n    # Formatting\n    yticklabels = list(range(n_splits)) + [\"class\", \"group\"]\n    ax.set(\n        yticks=np.arange(n_splits + 2) + 0.5,\n        yticklabels=yticklabels,\n        xlabel=\"Sample index\",\n        ylabel=\"CV iteration\",\n        ylim=[n_splits + 2.2, -0.2],\n        xlim=[0, 100],\n    )\n    ax.set_title(\"{}\".format(type(cv).__name__), fontsize=15)\n    return ax"}]},{"title":"Compare Cross-Validation Objects","body":["Compare Cross-Validation Objects","In this step, we will compare the cross-validation behavior for different scikit-learn cross-validation objects. We will loop through several common cross-validation objects, visualizing the behavior of each. Note how some use the group/class information while others do not."],"code":[{"lang":"python","text":"cvs = [\n    KFold,\n    GroupKFold,\n    ShuffleSplit,\n    StratifiedKFold,\n    StratifiedGroupKFold,\n    GroupShuffleSplit,\n    StratifiedShuffleSplit,\n    TimeSeriesSplit,\n]\n\nfor cv in cvs:\n    this_cv = cv(n_splits=n_splits)\n    fig, ax = plt.subplots(figsize=(6, 3))\n    plot_cv_indices(this_cv, X, y, groups, ax, n_splits)\n\n    ax.legend(\n        [Patch(color=cmap_cv(0.8)), Patch(color=cmap_cv(0.02))],\n        [\"Testing set\", \"Training set\"],\n        loc=(1.02, 0.8),\n    )\n    # Make the legend fit\n    plt.tight_layout()\n    fig.subplots_adjust(right=0.7)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"cvs = [\n    KFold,\n    GroupKFold,\n    ShuffleSplit,\n    StratifiedKFold,\n    StratifiedGroupKFold,\n    GroupShuffleSplit,\n    StratifiedShuffleSplit,\n    TimeSeriesSplit,\n]\n\nfor cv in cvs:\n    this_cv = cv(n_splits=n_splits)\n    fig, ax = plt.subplots(figsize=(6, 3))\n    plot_cv_indices(this_cv, X, y, groups, ax, n_splits)\n\n    ax.legend(\n        [Patch(color=cmap_cv(0.8)), Patch(color=cmap_cv(0.02))],\n        [\"Testing set\", \"Training set\"],\n        loc=(1.02, 0.8),\n    )\n    # Make the legend fit\n    plt.tight_layout()\n    fig.subplots_adjust(right=0.7)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plotting-predictions-with-cross-validation":{"intro":"In this lab, we will learn how to use cross-validation to visualize model predictions and errors using the cross_val_predict and PredictionErrorDisplay functions in scikit-learn. We will load the diabetes dataset, create an instance of a linear regression model, and use cross-validation to obtain an array of predictions. We will then use PredictionErrorDisplay to plot the actual versus predicted values, as well as the residuals versus predicted values.","steps":[{"title":"Load and Prepare Data","body":["First, we will load the diabetes dataset and prepare it for modeling. We will use load_diabetes function from scikit-learn to load the dataset into two arrays, X and y."],"code":[{"lang":"python","text":"from sklearn.datasets import load_diabetes\n\nX, y = load_diabetes(return_X_y=True)"}]},{"title":"Create a Linear Regression Model","body":["Create a Linear Regression Model","Next, we will create an instance of a linear regression model using the LinearRegression class from scikit-learn."],"code":[{"lang":"python","text":"from sklearn.linear_model import LinearRegression\n\nlr = LinearRegression()"}]},{"title":"Generate Cross-Validated Predictions","body":["Generate Cross-Validated Predictions","We will use cross_val_predict function from scikit-learn to generate cross-validated predictions."],"code":[{"lang":"python","text":"from sklearn.model_selection import cross_val_predict\n\ny_pred = cross_val_predict(lr, X, y, cv=10)"}]},{"title":"Visualize Prediction Errors","body":["We will use PredictionErrorDisplay from scikit-learn to visualize the prediction errors. We will plot the actual versus predicted values, as well as the residuals versus predicted values."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom sklearn.metrics import PredictionErrorDisplay\n\nfig, axs = plt.subplots(ncols=2, figsize=(8, 4))\nPredictionErrorDisplay.from_predictions(\n    y,\n    y_pred=y_pred,\n    kind=\"actual_vs_predicted\",\n    subsample=100,\n    ax=axs[0],\n    random_state=0,\n)\naxs[0].set_title(\"Actual vs. Predicted values\")\nPredictionErrorDisplay.from_predictions(\n    y,\n    y_pred=y_pred,\n    kind=\"residual_vs_predicted\",\n    subsample=100,\n    ax=axs[1],\n    random_state=0,\n)\naxs[1].set_title(\"Residuals vs. Predicted Values\")\nfig.suptitle(\"Plotting cross-validated predictions\")\nplt.tight_layout()\nplt.show()"}]},{"title":"Interpret Results","body":["From the visualizations, we can see that the actual versus predicted plot shows a relatively linear relationship with some variation. The residuals versus predicted values plot shows a relatively random pattern with no clear trend, indicating that the linear regression model may be a good fit for the data. However, it is important to note that we used cross_val_predict for visualization purposes only. It would be problematic to quantitatively assess the model performance by computing a single performance metric from the concatenated predictions returned by cross_val_predict when the different CV folds vary by size and…"],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-dbscan-clustering-algorithm":{"intro":"In this lab, we will use the DBSCAN (Density-Based Spatial Clustering of Applications with Noise) algorithm to cluster a synthetic dataset. DBSCAN is a clustering algorithm that identifies core samples in regions of high density and expands clusters from them. This algorithm is useful for data containing clusters of similar density.","steps":[{"title":"Data Generation","body":["We will use the make_blobs function from the sklearn.datasets module to generate a synthetic dataset with three clusters. The dataset will consist of 750 samples with a cluster standard deviation of 0.4. We will also standardize the data using the StandardScaler from the sklearn.preprocessing module."],"code":[{"lang":"python","text":"from sklearn.datasets import make_blobs\nfrom sklearn.preprocessing import StandardScaler\n\ncenters = [[1, 1], [-1, -1], [1, -1]]\nX, labels_true = make_blobs(\n    n_samples=750, centers=centers, cluster_std=0.4, random_state=0\n)\n\nX = StandardScaler().fit_transform(X)"}]},{"title":"Data Visualization","body":["We can visualize the resulting data using the matplotlib.pyplot module."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.scatter(X[:, 0], X[:, 1])\nplt.show()"}]},{"title":"Compute DBSCAN","body":["We will use the DBSCAN class from the sklearn.cluster module to compute the clusters. We will set the eps parameter to 0.3 and the min*samples parameter to 10. We can access the labels assigned by DBSCAN using the labels* attribute. Noisy samples are given the label -1. We will also calculate the number of clusters and the number of noise points."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.cluster import DBSCAN\nfrom sklearn import metrics\n\ndb = DBSCAN(eps=0.3, min_samples=10).fit(X)\nlabels = db.labels_\n\nn_clusters_ = len(set(labels)) - (1 if -1 in labels else 0)\nn_noise_ = list(labels).count(-1)\n\nprint(\"Estimated number of clusters: %d\" % n_clusters_)\nprint(\"Estimated number of noise points: %d\" % n_noise_)"}]},{"title":"Evaluation Metrics","body":["We can use evaluation metrics to quantify the quality of the resulting clusters. We will use the homogeneity, completeness, V-measure, adjusted Rand index, adjusted mutual information, and silhouette coefficient metrics. We will access these metrics from the sklearn.metrics module. If the ground truth labels are not known, evaluation can only be performed using the model results itself. In that case, the silhouette coefficient comes in handy."],"code":[{"lang":"python","text":"print(f\"Homogeneity: {metrics.homogeneity_score(labels_true, labels):.3f}\")\nprint(f\"Completeness: {metrics.completeness_score(labels_true, labels):.3f}\")\nprint(f\"V-measure: {metrics.v_measure_score(labels_true, labels):.3f}\")\nprint(f\"Adjusted Rand Index: {metrics.adjusted_rand_score(labels_true, labels):.3f}\")\nprint(f\"Adjusted Mutual Information: {metrics.adjusted_mutual_info_score(labels_true, labels):.3f}\")\nprint(f\"Silhouette Coefficient: {metrics.silhouette_score(X, labels):.3f}\")"}]},{"title":"Plot Results","body":["We will use the matplotlib.pyplot module to plot the results. Core samples (large dots) and non-core samples (small dots) are color-coded according to the assigned cluster. Samples tagged as noise are represented in black."],"code":[{"lang":"python","text":"unique_labels = set(labels)\ncore_samples_mask = np.zeros_like(labels, dtype=bool)\ncore_samples_mask[db.core_sample_indices_] = True\n\ncolors = [plt.cm.Spectral(each) for each in np.linspace(0, 1, len(unique_labels))]\nfor k, col in zip(unique_labels, colors):\n    if k == -1:\n        col = [0, 0, 0, 1]\n\n    class_member_mask = labels == k\n\n    xy = X[class_member_mask & core_samples_mask]\n    plt.plot(\n        xy[:, 0],\n        xy[:, 1],\n        \"o\",\n        markerfacecolor=tuple(col),\n        markeredgecolor=\"k\",\n        markersize=14,\n    )\n\n    xy = X[class_member_mask & ~core_samples_mask]\n    plt.plot(\n        xy[:, 0],\n        xy[:, 1],\n        \"o\",\n        markerfacecolor=tuple(col),\n        markeredgecolor=\"k\",\n        markersize=6,\n    )\n\nplt.title(f\"Estimated number of clusters: {n_clusters_}\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"unique_labels = set(labels)\ncore_samples_mask = np.zeros_like(labels, dtype=bool)\ncore_samples_mask[db.core_sample_indices_] = True\n\ncolors = [plt.cm.Spectral(each) for each in np.linspace(0, 1, len(unique_labels))]\nfor k, col in zip(unique_labels, colors):\n    if k == -1:\n        col = [0, 0, 0, 1]\n\n    class_member_mask = labels == k\n\n    xy = X[class_member_mask & core_samples_mask]\n    plt.plot(\n        xy[:, 0],\n        xy[:, 1],\n        \"o\",\n        markerfacecolor=tuple(col),\n        markeredgecolor=\"k\",\n        markersize=14,\n    )\n\n    xy = X[class_member_mask & ~core_samples_mask]\n    plt.plot(\n        xy[:, 0],\n        xy[:, 1],\n        \"o\",\n        markerfacecolor=tuple(col),\n        markeredgecolor=\"k\",\n        markersize=6,\n    )\n\nplt.title(f\"Estimated number of clusters: {n_clusters_}\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-detection-error-tradeoff-curve":{"intro":"In this tutorial, we will learn about Detection Error Tradeoff (DET) curves and compare them with Receiver Operating Characteristic (ROC) curves. DET curves are a variation of ROC curves, where False Negative Rate (FNR) is plotted on the y-axis instead of the True Positive Rate (TPR). We will use scikit-learn, a popular Python library for machine learning, to generate synthetic data and compare the statistical performance of two classifiers across thresholds using ROC and DET curves.","steps":[{"title":"Generate Synthetic Data","body":["We will use scikit-learn's make_classification function to generate synthetic data. This function generates a random n-class classification problem, with n_informative informative features, n_redundant redundant features, and n_clusters_per_class clusters per class. We will generate 1000 samples with 2 informative features and a random state of 1. We will then split the data into training and test sets with a 60/40 ratio."],"code":[{"lang":"python","text":"from sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\n\nX, y = make_classification(\n    n_samples=1_000,\n    n_features=2,\n    n_redundant=0,\n    n_informative=2,\n    random_state=1,\n    n_clusters_per_class=1,\n)\n\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.4, random_state=0)"}]},{"title":"Define the Classifiers","body":["We will define two different classifiers to compare their statistical performance across thresholds using ROC and DET curves. We will use scikit-learn's make_pipeline function to create a pipeline that scales the data using StandardScaler and trains a LinearSVC classifier. We will also use scikit-learn's RandomForestClassifier class to train a random forest classifier with a maximum depth of 5, 10 estimators, and a maximum of 1 feature."],"code":[{"lang":"python","text":"from sklearn.ensemble import RandomForestClassifier\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.svm import LinearSVC\n\nclassifiers = {\n    \"Linear SVM\": make_pipeline(StandardScaler(), LinearSVC(C=0.025, dual=\"auto\")),\n    \"Random Forest\": RandomForestClassifier(\n        max_depth=5, n_estimators=10, max_features=1\n    ),\n}"}]},{"title":"Plot ROC and DET Curves","body":["We will use scikit-learn's RocCurveDisplay and DetCurveDisplay classes to plot the ROC and DET curves, respectively. The RocCurveDisplay.from_estimator function calculates the ROC curve and plots it on the given axis. Similarly, the DetCurveDisplay.from_estimator function calculates the DET curve and plots it on the given axis. We will create two subplots, one for ROC curves and one for DET curves, and plot the curves for each classifier."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom sklearn.metrics import DetCurveDisplay, RocCurveDisplay\n\nfig, [ax_roc, ax_det] = plt.subplots(1, 2, figsize=(11, 5))\n\nfor name, clf in classifiers.items():\n    clf.fit(X_train, y_train)\n\n    RocCurveDisplay.from_estimator(clf, X_test, y_test, ax=ax_roc, name=name)\n    DetCurveDisplay.from_estimator(clf, X_test, y_test, ax=ax_det, name=name)\n\nax_roc.set_title(\"Receiver Operating Characteristic (ROC) curves\")\nax_det.set_title(\"Detection Error Tradeoff (DET) curves\")\n\nax_roc.grid(linestyle=\"--\")\nax_det.grid(linestyle=\"--\")\n\nplt.legend()\nplt.show()"}]},{"title":"Interpretation of Results","body":["It is easier to visually assess the overall performance of different classification algorithms using DET curves than using ROC curves. DET curves give direct feedback of the detection error tradeoff to aid in operating point analysis. The user can then decide the FNR they are willing to accept at the expense of the FPR (or vice-versa)."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plot-dict-face-patches":{"intro":"This lab demonstrates how to use the scikit-learn API to process a large dataset of faces and learn a set of 20 x 20 image patches that represent faces. The key aspect of this lab is the use of online learning, where we load and process images one at a time and extract 50 random patches from each image. We accumulate 500 patches (from 10 images) and then run the online KMeans object, MiniBatchKMeans' partial_fit method.","steps":[{"title":"Load the Data","body":["We first load the Olivetti faces dataset from scikit-learn."],"code":[{"lang":"python","text":"from sklearn import datasets\n\nfaces = datasets.fetch_olivetti_faces()"}]},{"title":"Learn the Dictionary of Images","body":["Learn the Dictionary of Images","We use MiniBatchKMeans to learn the dictionary of images. We set the number of clusters to 81, set a random state, and enable verbose mode. We then create a buffer to store patches and iterate through each image in the dataset. We extract 50 patches from each image and reshape the data. We then append the data to the buffer and increment the index. If the index is a multiple of 10, we concatenate the buffer and run partial_fit on the data. If the index is a multiple of 100, we print a message indicating the number of patches that have been fitted so far."],"code":[{"lang":"python","text":"import time\nimport numpy as np\nfrom sklearn.cluster import MiniBatchKMeans\nfrom sklearn.feature_extraction.image import extract_patches_2d\n\nprint(\"Learning the dictionary... \")\nrng = np.random.RandomState(0)\nkmeans = MiniBatchKMeans(n_clusters=81, random_state=rng, verbose=True, n_init=3)\npatch_size = (20, 20)\n\nbuffer = []\nt0 = time.time()\n\n# The online learning part: cycle over the whole dataset 6 times\nindex = 0\nfor _ in range(6):\n    for img in faces.images:\n        data = extract_patches_2d(img, patch_size, max_patches=50, random_state=rng)\n        data = np.reshape(data, (len(data), -1))\n        buffer.append(data)\n        index += 1\n        if index % 10 == 0:\n            data = np.concatenate(buffer, axis=0)\n            data -= np.mean(data, axis=0)\n            data /= np.std(data, axis=0)\n            kmeans.partial_fit(data)\n            buffer = []\n        if index % 100 == 0:\n            print(\"Partial fit of %4i out of %i\" % (index, 6 * len(faces.images)))\n\ndt = time.time() - t0\nprint(\"done in %.2fs.\" % dt)"}]},{"title":"Plot the Results","body":["Finally, we plot the patches of faces and display the training time."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.figure(figsize=(4.2, 4))\nfor i, patch in enumerate(kmeans.cluster_centers_):\n    plt.subplot(9, 9, i + 1)\n    plt.imshow(patch.reshape(patch_size), cmap=plt.cm.gray, interpolation=\"nearest\")\n    plt.xticks(())\n    plt.yticks(())\n\n\nplt.suptitle(\n    \"Patches of faces\\nTrain time %.1fs on %d patches\" % (dt, 8 * len(faces.images)),\n    fontsize=16,\n)\nplt.subplots_adjust(0.08, 0.02, 0.92, 0.85, 0.08, 0.23)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nplt.figure(figsize=(4.2, 4))\nfor i, patch in enumerate(kmeans.cluster_centers_):\n    plt.subplot(9, 9, i + 1)\n    plt.imshow(patch.reshape(patch_size), cmap=plt.cm.gray, interpolation=\"nearest\")\n    plt.xticks(())\n    plt.yticks(())\n\n\nplt.suptitle(\n    \"Patches of faces\\nTrain time %.1fs on %d patches\" % (dt, 8 * len(faces.images)),\n    fontsize=16,\n)\nplt.subplots_adjust(0.08, 0.02, 0.92, 0.85, 0.08, 0.23)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-feature-agglomeration-for-high-dimensional-d":{"intro":"This tutorial will demonstrate how to use feature agglomeration to merge similar features in a dataset. Feature agglomeration is useful when working with high-dimensional datasets by reducing the number of features while preserving the most important information.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries to perform feature agglomeration."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\n\nfrom sklearn import datasets, cluster\nfrom sklearn.feature_extraction.image import grid_to_graph"}]},{"title":"Load Dataset","body":["In this step, we will load the digits dataset from scikit-learn. This dataset contains images of handwritten digits from 0 to 9."],"code":[{"lang":"python","text":"digits = datasets.load_digits()\nimages = digits.images\nX = np.reshape(images, (len(images), -1))"}]},{"title":"Define Connectivity Matrix","body":["In this step, we will define the connectivity matrix using the grid_to_graph function from scikit-learn. This function creates a connectivity graph based on the pixel grid of the images."],"code":[{"lang":"python","text":"connectivity = grid_to_graph(*images[0].shape)"}]},{"title":"Perform Feature Agglomeration","body":["In this step, we will perform feature agglomeration using the FeatureAgglomeration class from scikit-learn. We will set the number of clusters to 32."],"code":[{"lang":"python","text":"agglo = cluster.FeatureAgglomeration(connectivity=connectivity, n_clusters=32)\nagglo.fit(X)\nX_reduced = agglo.transform(X)"}]},{"title":"Inverse Transform","body":["In this step, we will perform an inverse transform on the reduced dataset to restore the original number of features."],"code":[{"lang":"python","text":"X_restored = agglo.inverse_transform(X_reduced)\nimages_restored = np.reshape(X_restored, images.shape)"}]},{"title":"Visualize Results","body":["In this step, we will visualize the original images, the agglomerated images, and the labels assigned to each cluster."],"code":[{"lang":"python","text":"plt.figure(1, figsize=(4, 3.5))\nplt.clf()\nplt.subplots_adjust(left=0.01, right=0.99, bottom=0.01, top=0.91)\nfor i in range(4):\n    plt.subplot(3, 4, i + 1)\n    plt.imshow(images[i], cmap=plt.cm.gray, vmax=16, interpolation=\"nearest\")\n    plt.xticks(())\n    plt.yticks(())\n    if i == 1:\n        plt.title(\"Original data\")\n    plt.subplot(3, 4, 4 + i + 1)\n    plt.imshow(images_restored[i], cmap=plt.cm.gray, vmax=16, interpolation=\"nearest\")\n    if i == 1:\n        plt.title(\"Agglomerated data\")\n    plt.xticks(())\n    plt.yticks(())\n\nplt.subplot(3, 4, 10)\nplt.imshow(\n    np.reshape(agglo.labels_, images[0].shape),\n    interpolation=\"nearest\",\n    cmap=plt.cm.nipy_spectral,\n)\nplt.xticks(())\nplt.yticks(())\nplt.title(\"Labels\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(1, figsize=(4, 3.5))\nplt.clf()\nplt.subplots_adjust(left=0.01, right=0.99, bottom=0.01, top=0.91)\nfor i in range(4):\n    plt.subplot(3, 4, i + 1)\n    plt.imshow(images[i], cmap=plt.cm.gray, vmax=16, interpolation=\"nearest\")\n    plt.xticks(())\n    plt.yticks(())\n    if i == 1:\n        plt.title(\"Original data\")\n    plt.subplot(3, 4, 4 + i + 1)\n    plt.imshow(images_restored[i], cmap=plt.cm.gray, vmax=16, interpolation=\"nearest\")\n    if i == 1:\n        plt.title(\"Agglomerated data\")\n    plt.xticks(())\n    plt.yticks(())\n\nplt.subplot(3, 4, 10)\nplt.imshow(\n    np.reshape(agglo.labels_, images[0].shape),\n    interpolation=\"nearest\",\n    cmap=plt.cm.nipy_spectral,\n)\nplt.xticks(())\nplt.yticks(())\nplt.title(\"Labels\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-recognizing-hand-written-digits":{"intro":"This lab demonstrates how to use scikit-learn to recognize images of hand-written digits from 0-9.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will use matplotlib for visualization, datasets and metrics from sklearn to load and evaluate the dataset, and svm for training the support vector machine."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom sklearn import datasets, svm, metrics\nfrom sklearn.model_selection import train_test_split"}]},{"title":"Load and Visualize the Digits Dataset","body":["Load and Visualize the Digits Dataset","We will load the digits dataset which consists of 8x8 pixel images of digits. We will use imshow() method from matplotlib to visualize the first 4 images along with their corresponding labels."],"code":[{"lang":"python","text":"digits = datasets.load_digits()\n\n_, axes = plt.subplots(nrows=1, ncols=4, figsize=(10, 3))\nfor ax, image, label in zip(axes, digits.images, digits.target):\n    ax.set_axis_off()\n    ax.imshow(image, cmap=plt.cm.gray_r, interpolation=\"nearest\")\n    ax.set_title(\"Training: %i\" % label)"}]},{"title":"Prepare the Dataset","body":["We need to flatten the images to turn each 2-D array of grayscale values from shape (8, 8) into shape (64,). This will give us a dataset of shape (n_samples, n_features), where n_samples is the number of images and n_features is the total number of pixels in each image."],"code":[{"lang":"python","text":"n_samples = len(digits.images)\ndata = digits.images.reshape((n_samples, -1))"}]},{"title":"Split the Dataset","body":["We will split the dataset into 50% train and 50% test subsets using train_test_split() method from sklearn.model_selection."],"code":[{"lang":"python","text":"X_train, X_test, y_train, y_test = train_test_split(\n    data, digits.target, test_size=0.5, shuffle=False\n)"}]},{"title":"Train the Support Vector Machine","body":["Train the Support Vector Machine","We will train a support vector classifier on the train samples using svm.SVC() method from sklearn."],"code":[{"lang":"python","text":"clf = svm.SVC(gamma=0.001)\nclf.fit(X_train, y_train)"}]},{"title":"Predict and Evaluate the Model","body":["Predict and Evaluate the Model","We will use the trained model to predict the value of the digits for the samples in the test subset. Then, we will evaluate the model using metrics.classification_report() and metrics.ConfusionMatrixDisplay.from_predictions() methods from sklearn.metrics."],"code":[{"lang":"python","text":"predicted = clf.predict(X_test)\n\nprint(\n    f\"Classification report for classifier {clf}:\\n\"\n    f\"{metrics.classification_report(y_test, predicted)}\\n\"\n)\n\ndisp = metrics.ConfusionMatrixDisplay.from_predictions(y_test, predicted)\ndisp.figure_.suptitle(\"Confusion Matrix\")\nprint(f\"Confusion matrix:\\n{disp.confusion_matrix}\")"}]},{"title":"Rebuild Classification Report from Confusion Matrix","body":["Rebuild Classification Report from Confusion Matrix","If the results from evaluating a classifier are stored in the form of a confusion matrix and not in terms of y_true and y_pred, we can still build a classification report using metrics.classification_report() method as follows:"],"code":[{"lang":"python","text":"y_true = []\ny_pred = []\ncm = disp.confusion_matrix\n\nfor gt in range(len(cm)):\n    for pred in range(len(cm)):\n        y_true += [gt] * cm[gt][pred]\n        y_pred += [pred] * cm[gt][pred]\n\nprint(\n    \"Classification report rebuilt from confusion matrix:\\n\"\n    f\"{metrics.classification_report(y_true, y_pred)}\\n\"\n)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"y_true = []\ny_pred = []\ncm = disp.confusion_matrix\n\nfor gt in range(len(cm)):\n    for pred in range(len(cm)):\n        y_true += [gt] * cm[gt][pred]\n        y_pred += [pred] * cm[gt][pred]\n\nprint(\n    \"Classification report rebuilt from confusion matrix:\\n\"\n    f\"{metrics.classification_report(y_true, y_pred)}\\n\"\n)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-digits-classification-using-scikit-learn":{"intro":"This lab is a step-by-step tutorial on how to use classification techniques on the Digits dataset using scikit-learn. In this lab, we will load the dataset, preprocess the data, split the dataset into training and testing sets, and then use two different classification techniques (K-Nearest Neighbors and Logistic Regression) to classify the digits. Finally, we will compare the accuracy of both techniques.","steps":[{"title":"Load the Digits dataset","body":["We will start by loading the digits dataset using the load_digits function from scikit-learn. This function returns two arrays: X_digits containing the input data and y_digits containing the target labels."],"code":[{"lang":"python","text":"from sklearn import datasets\n\nX_digits, y_digits = datasets.load_digits(return_X_y=True)"}]},{"title":"Preprocess the data","body":["We will then preprocess the data by scaling the features to a range of [0, 1] using the maximum value of the data. This can be done by dividing the input data by the maximum value of the input data."],"code":[{"lang":"python","text":"X_digits = X_digits / X_digits.max()"}]},{"title":"Split the dataset into training and testing sets","body":["Split the dataset into training and testing sets","Next, we will split the dataset into training and testing sets using scikit-learn's train_test_split function. We will use 90% of the data for training and 10% for testing."],"code":[{"lang":"python","text":"from sklearn.model_selection import train_test_split\n\nX_train, X_test, y_train, y_test = train_test_split(X_digits, y_digits, test_size=0.1, random_state=42)"}]},{"title":"Train and test the K-Nearest Neighbors classifier","body":["Train and test the K-Nearest Neighbors classifier","We will now train a K-Nearest Neighbors (KNN) classifier using scikit-learn's KNeighborsClassifier function and test it on the testing set. We will then print the accuracy score of the classifier."],"code":[{"lang":"python","text":"from sklearn.neighbors import KNeighborsClassifier\n\nknn = KNeighborsClassifier()\nknn.fit(X_train, y_train)\nknn_score = knn.score(X_test, y_test)\n\nprint(\"KNN score: %f\" % knn_score)"}]},{"title":"Train and test the Logistic Regression classifier","body":["Train and test the Logistic Regression classifier","We will now train a Logistic Regression classifier using scikit-learn's LogisticRegression function and test it on the testing set. We will then print the accuracy score of the classifier."],"code":[{"lang":"python","text":"from sklearn.linear_model import LogisticRegression\n\nlogistic = LogisticRegression(max_iter=1000)\nlogistic.fit(X_train, y_train)\nlogistic_score = logistic.score(X_test, y_test)\n\nprint(\"Logistic Regression score: %f\" % logistic_score)"}]},{"title":"Compare the accuracy of both classifiers","body":["Compare the accuracy of both classifiers","Finally, we will compare the accuracy of both classifiers by printing the accuracy scores of both classifiers."],"code":[{"lang":"python","text":"print(\"KNN score: %f\" % knn_score)\nprint(\"Logistic Regression score: %f\" % logistic_score)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"print(\"KNN score: %f\" % knn_score)\nprint(\"Logistic Regression score: %f\" % logistic_score)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-image-denoising-with-kernel-pca":{"intro":"This lab demonstrates how to use Kernel PCA to denoise images. The idea is to learn a PCA basis on noise-free images and use it to reconstruct and denoise the noisy images. We use USPS digits dataset for this purpose.","steps":[{"title":"Load the dataset via OpenML","body":["We load the USPS digits dataset using fetch_openml() function from scikit-learn. The data is then normalized using MinMaxScaler()."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import fetch_openml\nfrom sklearn.preprocessing import MinMaxScaler\nfrom sklearn.model_selection import train_test_split\n\nX, y = fetch_openml(data_id=41082, as_frame=False, return_X_y=True, parser=\"pandas\")\nX = MinMaxScaler().fit_transform(X)"}]},{"title":"Create Training and Testing Sets","body":["Create Training and Testing Sets","We split the dataset into a training set with 1000 samples and a testing set with 100 samples. We add Gaussian noise to the testing set and create two copies of the original data; one with noise and one without noise."],"code":[{"lang":"python","text":"X_train, X_test, y_train, y_test = train_test_split(\n    X, y, stratify=y, random_state=0, train_size=1_000, test_size=100\n)\n\nrng = np.random.RandomState(0)\nnoise = rng.normal(scale=0.25, size=X_test.shape)\nX_test_noisy = X_test + noise\n\nnoise = rng.normal(scale=0.25, size=X_train.shape)\nX_train_noisy = X_train + noise"}]},{"title":"Plot Test Images","body":["We define a helper function to plot the test images. We use this function to plot the uncorrupted and noisy test images."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\ndef plot_digits(X, title):\n    fig, axs = plt.subplots(nrows=10, ncols=10, figsize=(8, 8))\n    for img, ax in zip(X, axs.ravel()):\n        ax.imshow(img.reshape((16, 16)), cmap=\"Greys\")\n        ax.axis(\"off\")\n    fig.suptitle(title, fontsize=24)\n\nplot_digits(X_test, \"Uncorrupted test images\")\nplot_digits(\n    X_test_noisy, f\"Noisy test images\\nMSE: {np.mean((X_test - X_test_noisy) ** 2):.2f}\"\n)"}]},{"title":"Learn the PCA Basis","body":["We learn the PCA basis using both linear PCA and kernel PCA. Kernel PCA uses radial basis function (RBF) kernel to learn the basis."],"code":[{"lang":"python","text":"from sklearn.decomposition import PCA, KernelPCA\n\npca = PCA(n_components=32, random_state=42)\nkernel_pca = KernelPCA(\n    n_components=400,\n    kernel=\"rbf\",\n    gamma=1e-3,\n    fit_inverse_transform=True,\n    alpha=5e-3,\n    random_state=42,\n)\n\npca.fit(X_train_noisy)\n_ = kernel_pca.fit(X_train_noisy)"}]},{"title":"Reconstruct and Denoise Test Images","body":["Reconstruct and Denoise Test Images","We transform and reconstruct the noisy test set using both PCA and kernel PCA. We then plot the reconstructed images to compare the results."],"code":[{"lang":"python","text":"X_reconstructed_kernel_pca = kernel_pca.inverse_transform(\n    kernel_pca.transform(X_test_noisy)\n)\nX_reconstructed_pca = pca.inverse_transform(pca.transform(X_test_noisy))\n\nplot_digits(X_test, \"Uncorrupted test images\")\nplot_digits(\n    X_reconstructed_pca,\n    f\"PCA reconstruction\\nMSE: {np.mean((X_test - X_reconstructed_pca) ** 2):.2f}\",\n)\nplot_digits(\n    X_reconstructed_kernel_pca,\n    (\n        \"Kernel PCA reconstruction\\n\"\n        f\"MSE: {np.mean((X_test - X_reconstructed_kernel_pca) ** 2):.2f}\"\n    ),\n)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"X_reconstructed_kernel_pca = kernel_pca.inverse_transform(\n    kernel_pca.transform(X_test_noisy)\n)\nX_reconstructed_pca = pca.inverse_transform(pca.transform(X_test_noisy))\n\nplot_digits(X_test, \"Uncorrupted test images\")\nplot_digits(\n    X_reconstructed_pca,\n    f\"PCA reconstruction\\nMSE: {np.mean((X_test - X_reconstructed_pca) ** 2):.2f}\",\n)\nplot_digits(\n    X_reconstructed_kernel_pca,\n    (\n        \"Kernel PCA reconstruction\\n\"\n        f\"MSE: {np.mean((X_test - X_reconstructed_kernel_pca) ** 2):.2f}\"\n    ),\n)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-kernel-density-estimation":{"intro":"Kernel Density Estimation (KDE) is a non-parametric density estimation technique. In this lab, we will learn how to use KDE to generate new samples of data. We will use the scikit-learn library to implement this technique.","steps":[{"title":"Load Data","body":["First, we load the digits dataset from scikit-learn. This dataset contains 8x8 images of digits from 0 to 9. We will use Principal Component Analysis (PCA) to reduce the dimension of the dataset to 15."],"code":[{"lang":"python","text":"from sklearn.datasets import load_digits\nfrom sklearn.decomposition import PCA\n\n# load the digits dataset\ndigits = load_digits()\n\n# reduce the dimension of the dataset to 15 using PCA\npca = PCA(n_components=15, whiten=False)\ndata = pca.fit_transform(digits.data)"}]},{"title":"Optimize Bandwidth","body":["We use grid search cross-validation to optimize the bandwidth parameter of the KDE. The bandwidth parameter controls the smoothness of the density estimate."],"code":[{"lang":"python","text":"from sklearn.neighbors import KernelDensity\nfrom sklearn.model_selection import GridSearchCV\nimport numpy as np\n\n# use grid search cross-validation to optimize the bandwidth\nparams = {\"bandwidth\": np.logspace(-1, 1, 20)}\ngrid = GridSearchCV(KernelDensity(), params)\ngrid.fit(data)\n\nprint(\"best bandwidth: {0}\".format(grid.best_estimator_.bandwidth))\n\n# use the best estimator to compute the kernel density estimate\nkde = grid.best_estimator_"}]},{"title":"Generate New Samples","body":["We use the best estimator to sample 44 new points from the data. We then transform the new data back to its original 64 dimension using the inverse of PCA."],"code":[{"lang":"python","text":"# sample 44 new points from the data\nnew_data = kde.sample(44, random_state=0)\nnew_data = pca.inverse_transform(new_data)"}]},{"title":"Plot Results","body":["We plot the original digits and the resampled digits side by side in a 4x11 grid."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# turn data into a 4x11 grid\nnew_data = new_data.reshape((4, 11, -1))\nreal_data = digits.data[:44].reshape((4, 11, -1))\n\n# plot real digits and resampled digits\nfig, ax = plt.subplots(9, 11, subplot_kw=dict(xticks=[], yticks=[]))\nfor j in range(11):\n    ax[4, j].set_visible(False)\n    for i in range(4):\n        im = ax[i, j].imshow(\n            real_data[i, j].reshape((8, 8)), cmap=plt.cm.binary, interpolation=\"nearest\"\n        )\n        im.set_clim(0, 16)\n        im = ax[i + 5, j].imshow(\n            new_data[i, j].reshape((8, 8)), cmap=plt.cm.binary, interpolation=\"nearest\"\n        )\n        im.set_clim(0, 16)\n\nax[0, 5].set_title(\"Selection from the input data\")\nax[5, 5].set_title('\"New\" digits drawn from the kernel density model')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\n# turn data into a 4x11 grid\nnew_data = new_data.reshape((4, 11, -1))\nreal_data = digits.data[:44].reshape((4, 11, -1))\n\n# plot real digits and resampled digits\nfig, ax = plt.subplots(9, 11, subplot_kw=dict(xticks=[], yticks=[]))\nfor j in range(11):\n    ax[4, j].set_visible(False)\n    for i in range(4):\n        im = ax[i, j].imshow(\n            real_data[i, j].reshape((8, 8)), cmap=plt.cm.binary, interpolation=\"nearest\"\n        )\n        im.set_clim(0, 16)\n        im = ax[i + 5, j].imshow(\n            new_data[i, j].reshape((8, 8)), cmap=plt.cm.binary, interpolation=\"nearest\"\n        )\n        im.set_clim(0, 16)\n\nax[0, 5].set_title(\"Selection from the input data\")\nax[5, 5].set_title('\"New\" digits drawn from the kernel density model')\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-digit-dataset-analysis":{"intro":"In this lab, we will be exploring the scikit-learn digits dataset. This dataset consists of 1797 8x8 pixel images, each representing a handwritten digit from 0-9. Our goal is to analyze this dataset and understand how we can utilize it to classify handwritten digits using machine learning algorithms.","steps":[{"title":"Importing the Dataset","body":["The first step is to import the digits dataset from scikit-learn using the following code:"],"code":[{"lang":"python","text":"from sklearn import datasets\n\n# Load the digits dataset\ndigits = datasets.load_digits()"}]},{"title":"Visualizing the Dataset","body":["To get a better understanding of the dataset, we can visualize a sample image using matplotlib. The following code displays the last digit in the dataset:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Display the last digit\nplt.figure(1, figsize=(3, 3))\nplt.imshow(digits.images[-1], cmap=plt.cm.gray_r, interpolation=\"nearest\")\nplt.show()"}]},{"title":"Preparing the Dataset for Machine Learning","body":["Preparing the Dataset for Machine Learning","Before we can train a machine learning model on the dataset, we need to prepare the data by splitting it into training and testing sets. We can do this using scikit-learn's train_test_split function:"],"code":[{"lang":"python","text":"from sklearn.model_selection import train_test_split\n\n# Split the dataset into training and testing sets\nX_train, X_test, y_train, y_test = train_test_split(digits.data, digits.target, test_size=0.2, random_state=42)"}]},{"title":"Training a Machine Learning Model","body":["Training a Machine Learning Model","Now that we have prepared the dataset, we can train a machine learning model on the training data. In this example, we will be using a Support Vector Machine (SVM) algorithm:"],"code":[{"lang":"python","text":"from sklearn.svm import SVC\n\n# Create the SVM classifier\nclf = SVC(kernel='linear')\n\n# Train the classifier on the training data\nclf.fit(X_train, y_train)"}]},{"title":"Evaluating the Model","body":["To evaluate the performance of our model, we can use scikit-learn's accuracy_score function:"],"code":[{"lang":"python","text":"from sklearn.metrics import accuracy_score\n\n# Predict the labels of the test set\ny_pred = clf.predict(X_test)\n\n# Calculate the accuracy of the model\naccuracy = accuracy_score(y_test, y_pred)\n\n# Print the accuracy of the model\nprint(\"Accuracy:\", accuracy)"}]},{"title":"Improving the Model","body":["If the accuracy of our model is not satisfactory, we can try improving it by tuning the hyperparameters of the SVM algorithm. For example, we can try changing the value of the C parameter:"],"code":[{"lang":"python","text":"# Create the SVM classifier with a different value of C\nclf = SVC(kernel='linear', C=0.1)\n\n# Train the classifier on the training data\nclf.fit(X_train, y_train)\n\n# Predict the labels of the test set\ny_pred = clf.predict(X_test)\n\n# Calculate the accuracy of the model\naccuracy = accuracy_score(y_test, y_pred)\n\n# Print the accuracy of the model\nprint(\"Accuracy:\", accuracy)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create the SVM classifier with a different value of C\nclf = SVC(kernel='linear', C=0.1)\n\n# Train the classifier on the training data\nclf.fit(X_train, y_train)\n\n# Predict the labels of the test set\ny_pred = clf.predict(X_test)\n\n# Calculate the accuracy of the model\naccuracy = accuracy_score(y_test, y_pred)\n\n# Print the accuracy of the model\nprint(\"Accuracy:\", accuracy)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-agglomerative-clustering-on-digits-dataset":{"intro":"This lab illustrates various linkage options for agglomerative clustering on a 2D embedding of the digits dataset. The goal of this lab is to show how different linkage strategies behave and not to find good clusters for the digits. This is why the example works on a 2D embedding.","steps":[{"title":"Import Libraries","body":["We start by importing the necessary libraries for this lab. We will be using numpy, matplotlib, manifold, and datasets from scikit-learn to perform agglomerative clustering."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import pyplot as plt\nfrom time import time\nfrom sklearn import manifold, datasets\nfrom sklearn.cluster import AgglomerativeClustering"}]},{"title":"Load and Prepare the Dataset","body":["We load the digits dataset and prepare it for clustering by extracting the data and target labels. We also set the random seed to zero to ensure reproducibility."],"code":[{"lang":"python","text":"digits = datasets.load_digits()\nX, y = digits.data, digits.target\nn_samples, n_features = X.shape\nnp.random.seed(0)"}]},{"title":"Visualize the Dataset","body":["We visualize the dataset by computing a 2D embedding of the digits dataset using manifold.SpectralEmbedding() and plotting the scatter plot with different markers for each digit."],"code":[{"lang":"python","text":"def plot_dataset(X_red):\n    x_min, x_max = np.min(X_red, axis=0), np.max(X_red, axis=0)\n    X_red = (X_red - x_min) / (x_max - x_min)\n\n    plt.figure(figsize=(6, 4))\n    for digit in digits.target_names:\n        plt.scatter(\n            *X_red[y == digit].T,\n            marker=f\"${digit}$\",\n            s=50,\n            alpha=0.5,\n        )\n\n    plt.xticks([])\n    plt.yticks([])\n    plt.title('Digits Dataset Scatter Plot', size=17)\n    plt.axis(\"off\")\n    plt.tight_layout(rect=[0, 0.03, 1, 0.95])\n\nprint(\"Computing embedding\")\nX_red = manifold.SpectralEmbedding(n_components=2).fit_transform(X)\nprint(\"Done.\")\nplot_dataset(X_red)"}]},{"title":"Agglomerative Clustering with Different Linkage Strategies","body":["Agglomerative Clustering with Different Linkage Strategies","We perform agglomerative clustering with different linkage strategies: ward, average, complete, and single. We set the number of clusters to 10 for all the strategies. We then plot the clustering results using different colors for each digit."],"code":[{"lang":"python","text":"def plot_clustering(X_red, labels, title=None):\n    x_min, x_max = np.min(X_red, axis=0), np.max(X_red, axis=0)\n    X_red = (X_red - x_min) / (x_max - x_min)\n\n    plt.figure(figsize=(6, 4))\n    for digit in digits.target_names:\n        plt.scatter(\n            *X_red[y == digit].T,\n            marker=f\"${digit}$\",\n            s=50,\n            c=plt.cm.nipy_spectral(labels[y == digit] / 10),\n            alpha=0.5,\n        )\n\n    plt.xticks([])\n    plt.yticks([])\n    if title is not None:\n        plt.title(title, size=17)\n    plt.axis(\"off\")\n    plt.tight_layout(rect=[0, 0.03, 1, 0.95])\n\nfor linkage in (\"ward\", \"average\", \"complete\", \"single\"):\n    clustering = AgglomerativeClustering(linkage=linkage, n_clusters=10)\n    t0 = time()\n    clustering.fit(X_red)\n    print(\"%s :\\t%.2fs\" % (linkage, time() - t0))\n\n    plot_clustering(X_red, clustering.labels_, \"%s linkage\" % linkage)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def plot_clustering(X_red, labels, title=None):\n    x_min, x_max = np.min(X_red, axis=0), np.max(X_red, axis=0)\n    X_red = (X_red - x_min) / (x_max - x_min)\n\n    plt.figure(figsize=(6, 4))\n    for digit in digits.target_names:\n        plt.scatter(\n            *X_red[y == digit].T,\n            marker=f\"${digit}$\",\n            s=50,\n            c=plt.cm.nipy_spectral(labels[y == digit] / 10),\n            alpha=0.5,\n        )\n\n    plt.xticks([])\n    plt.yticks([])\n    if title is not None:\n        plt.title(title, size=17)\n    plt.axis(\"off\")\n    plt.tight_layout(rect=[0, 0.03, 1, 0.95])\n\nfor linkage in (\"ward\", \"average\", \"complete\", \"single\"):\n    clustering = AgglomerativeClustering(linkage=linkage, n_clusters=10)\n    t0 = time()\n    clustering.fit(X_red)\n    print(\"%s :\\t%.2fs\" % (linkage, time() - t0))\n\n    plot_clustering(X_red, clustering.labels_, \"%s linkage\" % linkage)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plot-digits-pipe":{"intro":"In this lab, we will build a pipeline for dimensionality reduction and classification using Principal Component Analysis (PCA) and Logistic Regression. We will use the scikit-learn library to perform unsupervised dimensionality reduction on the digits dataset using PCA. We will then use a logistic regression model for classification. We will use GridSearchCV to set the dimensionality of the PCA and find the best combination of PCA truncation and classifier regularization.","steps":[{"title":"Import Required Libraries","body":["We will first import the required libraries for the implementation of the pipeline."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nimport pandas as pd\n\nfrom sklearn import datasets\nfrom sklearn.decomposition import PCA\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.model_selection import GridSearchCV\nfrom sklearn.preprocessing import StandardScaler"}]},{"title":"Define Pipeline Components","body":["We will define the pipeline components including the PCA, Standard Scaler and Logistic Regression. We will set the tolerance to a large value to make the example faster."],"code":[{"lang":"python","text":"# Define a pipeline to search for the best combination of PCA truncation\n# and classifier regularization.\npca = PCA()\n# Define a Standard Scaler to normalize inputs\nscaler = StandardScaler()\n\nlogistic = LogisticRegression(max_iter=10000, tol=0.1)\n\npipe = Pipeline(steps=[(\"scaler\", scaler), (\"pca\", pca), (\"logistic\", logistic)])"}]},{"title":"Load Dataset and Define Parameters for GridSearchCV","body":["Load Dataset and Define Parameters for GridSearchCV","We will load the digits dataset and define parameters for GridSearchCV. We will set the parameter for PCA truncation and classifier regularization."],"code":[{"lang":"python","text":"X_digits, y_digits = datasets.load_digits(return_X_y=True)\n\nparam_grid = {\n    \"pca__n_components\": [5, 15, 30, 45, 60],\n    \"logistic__C\": np.logspace(-4, 4, 4),\n}"}]},{"title":"Perform GridSearchCV","body":["We will perform GridSearchCV to find the best combination of PCA truncation and classifier regularization."],"code":[{"lang":"python","text":"search = GridSearchCV(pipe, param_grid, n_jobs=2)\nsearch.fit(X_digits, y_digits)"}]},{"title":"Print Best Parameters and Score","body":["Print Best Parameters and Score","We will print the best parameters and score obtained from the GridSearchCV."],"code":[{"lang":"python","text":"print(\"Best parameter (CV score=%0.3f):\" % search.best_score_)\nprint(search.best_params_)"}]},{"title":"Plot PCA Spectrum","body":["We will plot the PCA spectrum to visualize the explained variance ratio of each principal component."],"code":[{"lang":"python","text":"pca.fit(X_digits)\n\nfig, (ax0, ax1) = plt.subplots(nrows=2, sharex=True, figsize=(6, 6))\nax0.plot(\n    np.arange(1, pca.n_components_ + 1), pca.explained_variance_ratio_, \"+\", linewidth=2\n)\nax0.set_ylabel(\"PCA explained variance ratio\")\n\nax0.axvline(\n    search.best_estimator_.named_steps[\"pca\"].n_components,\n    linestyle=\":\",\n    label=\"n_components chosen\",\n)\nax0.legend(prop=dict(size=12))"}]},{"title":"Find Best Classifier Results","body":["For each number of components, we will find the best classifier results."],"code":[{"lang":"python","text":"results = pd.DataFrame(search.cv_results_)\ncomponents_col = \"param_pca__n_components\"\nbest_clfs = results.groupby(components_col).apply(\n    lambda g: g.nlargest(1, \"mean_test_score\")\n)"}]},{"title":"Plot Classification Accuracy","body":["We will plot the classification accuracy for each number of components."],"code":[{"lang":"python","text":"best_clfs.plot(\n    x=components_col, y=\"mean_test_score\", yerr=\"std_test_score\", legend=False, ax=ax1\n)\nax1.set_ylabel(\"Classification accuracy (val)\")\nax1.set_xlabel(\"n_components\")\n\nplt.xlim(-1, 70)\n\nplt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"best_clfs.plot(\n    x=components_col, y=\"mean_test_score\", yerr=\"std_test_score\", legend=False, ax=ax1\n)\nax1.set_ylabel(\"Classification accuracy (val)\")\nax1.set_xlabel(\"n_components\")\n\nplt.xlim(-1, 70)\n\nplt.tight_layout()\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-discretizing-continuous-features-with-kbinsd":{"intro":"This lab demonstrates how to discretize continuous features using the KBinsDiscretizer class in Scikit-learn. Discretization is the process of transforming continuous features into discrete features by dividing the feature values into a set of bins. This can be useful when working with linear models that can only model linear relationships, or to reduce the complexity of decision trees.","steps":[{"title":"Load the Required Libraries","body":["In this step, we will import the required libraries."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\n\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.preprocessing import KBinsDiscretizer\nfrom sklearn.tree import DecisionTreeRegressor"}]},{"title":"Create the Dataset","body":["In this step, we will create a dataset with a continuous input feature and a continuous output feature. We will use the numpy.random.RandomState() method to generate random numbers for the input feature, and the numpy.sin() method to generate the output feature."],"code":[{"lang":"python","text":"rnd = np.random.RandomState(42)\nX = rnd.uniform(-3, 3, size=100)\ny = np.sin(X) + rnd.normal(size=len(X)) / 3\nX = X.reshape(-1, 1)"}]},{"title":"Visualize the Dataset","body":["In this step, we will visualize the dataset using a scatter plot."],"code":[{"lang":"python","text":"plt.scatter(X, y, color='black')\nplt.show()"}]},{"title":"Discretize the Input Feature","body":["In this step, we will use the KBinsDiscretizer class to discretize the input feature. We will create 10 bins and use one-hot encoding to transform the data."],"code":[{"lang":"python","text":"enc = KBinsDiscretizer(n_bins=10, encode=\"onehot\")\nX_binned = enc.fit_transform(X)"}]},{"title":"Visualize the Discretized Dataset","body":["Visualize the Discretized Dataset","In this step, we will visualize the discretized dataset using a scatter plot."],"code":[{"lang":"python","text":"plt.scatter(X_binned, y, color='black')\nplt.show()"}]},{"title":"Train a Linear Regression Model","body":["Train a Linear Regression Model","In this step, we will train a linear regression model on the original dataset."],"code":[{"lang":"python","text":"reg = LinearRegression().fit(X, y)"}]},{"title":"Train a Decision Tree Model","body":["In this step, we will train a decision tree model on the original dataset."],"code":[{"lang":"python","text":"reg = DecisionTreeRegressor(min_samples_split=3, random_state=0).fit(X, y)"}]},{"title":"Train a Linear Regression Model on the Discretized Dataset","body":["Train a Linear Regression Model on the Discretized Dataset","In this step, we will train a linear regression model on the discretized dataset."],"code":[{"lang":"python","text":"reg = LinearRegression().fit(X_binned, y)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# predict with original dataset\nfig, (ax1, ax2) = plt.subplots(ncols=2, sharey=True, figsize=(10, 4))\nline = np.linspace(-3, 3, 1000, endpoint=False).reshape(-1, 1)\nreg = LinearRegression().fit(X, y)\nax1.plot(line, reg.predict(line), linewidth=2, color=\"green\", label=\"linear regression\")\nreg = DecisionTreeRegressor(min_samples_split=3, random_state=0).fit(X, y)\nax1.plot(line, reg.predict(line), linewidth=2, color=\"red\", label=\"decision tree\")\nax1.plot(X[:, 0], y, \"o\", c=\"k\")\nax1.legend(loc=\"best\")\nax1.set_ylabel(\"Regression output\")\nax1.set_xlabel(\"Input feature\")\nax1.set_title(\"Result before discretization\")\n\n# predict with transformed dataset\nline_binned = enc.transform(line)\nreg = LinearRegression().fit(X_binned, y)\nax2.plot(\n    line,\n    reg.predict(line_binned),\n    linewidth=2,\n    color=\"green\",\n    linestyle=\"-\",\n    label=\"linear regression\",\n)\nreg = DecisionTreeRegressor(min_samples_split=3, random_state=0).fit(X_binned, y)\nax2.plot(\n    line,\n    reg.predict(line_binned),\n    linewidth=2,\n    color=\"red\",\n    linestyle=\":\",\n    label=\"decision tree\",\n)\nax2.plot(X[:, 0], y, \"o\", c=\"k\")\nax2.vlines(enc.bin_edges_[0], *plt.gca().get_ylim(), linewidth=1, alpha=0.2)\nax2.legend(loc=\"best\")\nax2.set_xlabel(\"Input feature\")\nax2.set_title(\"Result after discretization\")\n\nplt.tight_layout()\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-feature-discretization-for-classification":{"intro":"In machine learning, feature discretization is a method of reducing the number of continuous variables in a dataset by creating bins or intervals to represent them. This method can be useful in cases where the number of continuous variables is large, and the algorithm needs to be simplified for easier analysis. In this lab, we will demonstrate feature discretization on synthetic classification datasets.","steps":[{"title":"Import Libraries","body":["In this step, we will import the required libraries for the lab. We will be using the scikit-learn library for machine learning tasks, numpy for mathematical operations, and matplotlib for data visualization."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import ListedColormap\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.datasets import make_moons, make_circles, make_classification\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.model_selection import GridSearchCV\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import KBinsDiscretizer\nfrom sklearn.svm import SVC, LinearSVC\nfrom sklearn.ensemble import GradientBoostingClassifier\nfrom sklearn.utils._testing import ignore_warnings\nfrom sklearn.exceptions import ConvergenceWarning"}]},{"title":"Prepare the Data","body":["In this step, we will prepare the synthetic classification datasets for feature discretization. We will use the scikit-learn library to generate three different datasets: moons, concentric circles, and linearly separable data."],"code":[{"lang":"python","text":"h = 0.02  # step size in the mesh\n\nn_samples = 100\ndatasets = [\n    make_moons(n_samples=n_samples, noise=0.2, random_state=0),\n    make_circles(n_samples=n_samples, noise=0.2, factor=0.5, random_state=1),\n    make_classification(\n        n_samples=n_samples,\n        n_features=2,\n        n_redundant=0,\n        n_informative=2,\n        random_state=2,\n        n_clusters_per_class=1,\n    ),\n]"}]},{"title":"Define Classifiers and Parameters","body":["Define Classifiers and Parameters","In this step, we will define the classifiers and parameters to be used in the feature discretization process. We will create a list of classifiers that includes logistic regression, linear support vector machine (SVM), gradient boosting classifier, and SVM with a radial basis function kernel. We will also define a set of parameters for each classifier to be used in the GridSearchCV algorithm."],"code":[{"lang":"python","text":"# list of (estimator, param_grid), where param_grid is used in GridSearchCV\n# The parameter spaces in this example are limited to a narrow band to reduce\n# its runtime. In a real use case, a broader search space for the algorithms\n# should be used.\nclassifiers = [\n    (\n        make_pipeline(StandardScaler(), LogisticRegression(random_state=0)),\n        {\"logisticregression__C\": np.logspace(-1, 1, 3)},\n    ),\n    (\n        make_pipeline(StandardScaler(), LinearSVC(random_state=0, dual=\"auto\")),\n        {\"linearsvc__C\": np.logspace(-1, 1, 3)},\n    ),\n    (\n        make_pipeline(\n            StandardScaler(),\n            KBinsDiscretizer(encode=\"onehot\"),\n            LogisticRegression(random_state=0),\n        ),\n        {\n            \"kbinsdiscretizer__n_bins\": np.arange(5, 8),\n            \"logisticregression__C\": np.logspace(-1, 1, 3),\n        },\n    ),\n    (\n        make_pipeline(\n            StandardScaler(),\n            KBinsDiscretizer(encode=\"onehot\"),\n            LinearSVC(random_state=0, dual=\"auto\"),\n        ),\n        {\n            \"kbinsdiscretizer__n_bins\": np.arange(5, 8),\n            \"linearsvc__C\": np.logspace(-1, 1, 3),\n        },\n    ),\n    (\n        make_pipeline(\n            StandardScaler(), GradientBoostingClassifier(n_estimators=5, random_state=0)\n        ),\n        {\"gradientboostingclassifier__learning_rate\": np.logspace(-2, 0, 5)},\n    ),\n    (\n        make_pipeline(StandardScaler(), SVC(random_state=0)),\n        {\"svc__C\": np.logspace(-1, 1, 3)},\n    ),\n]\n\nnames = [get_name(e).replace(\"StandardScaler + \", \"\") for e, _ in classifiers]"}]},{"title":"Visualize the Data","body":["In this step, we will visualize the synthetic classification datasets before feature discretization. We will plot the training and testing points for each dataset."],"code":[{"lang":"python","text":"fig, axes = plt.subplots(\n    nrows=len(datasets), ncols=len(classifiers) + 1, figsize=(21, 9)\n)\n\ncm_piyg = plt.cm.PiYG\ncm_bright = ListedColormap([\"#b30065\", \"#178000\"])\n\n# iterate over datasets\nfor ds_cnt, (X, y) in enumerate(datasets):\n    print(f\"\\ndataset {ds_cnt}\\n---------\")\n\n    # split into training and test part\n    X_train, X_test, y_train, y_test = train_test_split(\n        X, y, test_size=0.5, random_state=42\n    )\n\n    # create the grid for background colors\n    x_min, x_max = X[:, 0].min() - 0.5, X[:, 0].max() + 0.5\n    y_min, y_max = X[:, 1].min() - 0.5, X[:, 1].max() + 0.5\n    xx, yy = np.meshgrid(np.arange(x_min, x_max, h), np.arange(y_min, y_max, h))\n\n    # plot the dataset first\n    ax = axes[ds_cnt, 0]\n    if ds_cnt == 0:\n        ax.set_title(\"Input data\")\n    # plot the training points\n    ax.scatter(X_train[:, 0], X_train[:, 1], c=y_train, cmap=cm_bright, edgecolors=\"k\")\n    # and testing points\n    ax.scatter(\n        X_test[:, 0], X_test[:, 1], c=y_test, cmap=cm_bright, alpha=0.6, edgecolors=\"k\"\n    )\n    ax.set_xlim(xx.min(), xx.max())\n    ax.set_ylim(yy.min(), yy.max())\n    ax.set_xticks(())\n    ax.set_yticks(())"}]},{"title":"Implement Feature Discretization","body":["Implement Feature Discretization","In this step, we will implement feature discretization on the datasets using the KBinsDiscretizer class from scikit-learn. This will discretize the features by creating a set of bins and then one-hot encoding the discrete values. We will then fit the data to a linear classifier and evaluate the performance."],"code":[{"lang":"python","text":"# iterate over classifiers\nfor est_idx, (name, (estimator, param_grid)) in enumerate(zip(names, classifiers)):\n    ax = axes[ds_cnt, est_idx + 1]\n\n    clf = GridSearchCV(estimator=estimator, param_grid=param_grid)\n    with ignore_warnings(category=ConvergenceWarning):\n        clf.fit(X_train, y_train)\n    score = clf.score(X_test, y_test)\n    print(f\"{name}: {score:.2f}\")\n\n    # plot the decision boundary. For that, we will assign a color to each\n    # point in the mesh [x_min, x_max]*[y_min, y_max].\n    if hasattr(clf, \"decision_function\"):\n        Z = clf.decision_function(np.column_stack([xx.ravel(), yy.ravel()]))\n    else:\n        Z = clf.predict_proba(np.column_stack([xx.ravel(), yy.ravel()]))[:, 1]\n\n    # put the result into a color plot\n    Z = Z.reshape(xx.shape)\n    ax.contourf(xx, yy, Z, cmap=cm_piyg, alpha=0.8)\n\n    # plot the training points\n    ax.scatter(\n        X_train[:, 0], X_train[:, 1], c=y_train, cmap=cm_bright, edgecolors=\"k\"\n    )\n    # and testing points\n    ax.scatter(\n        X_test[:, 0],\n        X_test[:, 1],\n        c=y_test,\n        cmap=cm_bright,\n        edgecolors=\"k\",\n        alpha=0.6,\n    )\n    ax.set_xlim(xx.min(), xx.max())\n    ax.set_ylim(yy.min(), yy.max())\n    ax.set_xticks(())\n    ax.set_yticks(())\n\n    if ds_cnt == 0:\n        ax.set_title(name.replace(\" + \", \"\\n\"))\n    ax.text(\n        0.95,\n        0.06,\n        (f\"{score:.2f}\").lstrip(\"0\"),\n        size=15,\n        bbox=dict(boxstyle=\"round\", alpha=0.8, facecolor=\"white\"),\n        transform=ax.transAxes,"}]},{"title":"Visualize Results","body":["In this step, we will visualize the results of the feature discretization process. We will plot the classification accuracy on the test set for each classifier and dataset."],"code":[{"lang":"python","text":"plt.tight_layout()\n\n# Add suptitles above the figure\nplt.subplots_adjust(top=0.90)\nsuptitles = [\n    \"Linear classifiers\",\n    \"Feature discretization and linear classifiers\",\n    \"Non-linear classifiers\",\n]\nfor i, suptitle in zip([1, 3, 5], suptitles):\n    ax = axes[0, i]\n    ax.text(\n        1.05,\n        1.25,\n        suptitle,\n        transform=ax.transAxes,\n        horizontalalignment=\"center\",\n        size=\"x-large\",\n    )\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.tight_layout()\n\n# Add suptitles above the figure\nplt.subplots_adjust(top=0.90)\nsuptitles = [\n    \"Linear classifiers\",\n    \"Feature discretization and linear classifiers\",\n    \"Non-linear classifiers\",\n]\nfor i, suptitle in zip([1, 3, 5], suptitles):\n    ax = axes[0, i]\n    ax.text(\n        1.05,\n        1.25,\n        suptitle,\n        transform=ax.transAxes,\n        horizontalalignment=\"center\",\n        size=\"x-large\",\n    )\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-demonstrating-kbinsdiscretizer-strategies":{"intro":"In this lab, we will explore the different strategies available in the KBinsDiscretizer class of the Python scikit-learn library. KBinsDiscretizer is a class for discretizing continuous features into categorical features by binning the continuous data. We will visualize the different strategies by applying them to different datasets.","steps":[{"title":"Import Libraries","body":["We will begin by importing the necessary libraries. We will be using numpy, matplotlib.pyplot, make_blobs, and KBinsDiscretizer from the sklearn.preprocessing module."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.preprocessing import KBinsDiscretizer\nfrom sklearn.datasets import make_blobs"}]},{"title":"Create Datasets","body":["We will create three datasets for visualization purposes. The first dataset will be a random set of 200 samples from a uniform distribution between -3 and 3 in both dimensions. The second dataset will be a set of 200 samples generated using the make_blobs function from sklearn.datasets. The third dataset will also be generated using the make_blobs function."],"code":[{"lang":"python","text":"n_samples = 200\ncenters_0 = np.array([[0, 0], [0, 5], [2, 4], [8, 8]])\ncenters_1 = np.array([[0, 0], [3, 1]])\n\nX_list = [\n    np.random.RandomState(42).uniform(-3, 3, size=(n_samples, 2)),\n    make_blobs(\n        n_samples=[n_samples // 10, n_samples * 4 // 10, n_samples // 10, n_samples * 4 // 10],\n        cluster_std=0.5,\n        centers=centers_0,\n        random_state=42,\n    )[0],\n    make_blobs(\n        n_samples=[n_samples // 5, n_samples * 4 // 5],\n        cluster_std=0.5,\n        centers=centers_1,\n        random_state=42,\n    )[0],\n]"}]},{"title":"Apply Different Strategies","body":["We will now apply the three different strategies available in KBinsDiscretizer to each of the datasets. The strategies are:","• 'uniform': The discretization is uniform in each feature, which means that the bin widths are constant in each dimension. • 'quantile': The discretization is done on the quantiled values, which means that each bin has approximately the same number of samples. • 'kmeans': The discretization is based on the centroids of a KMeans clustering procedure."],"code":[{"lang":"python","text":"strategies = [\"uniform\", \"quantile\", \"kmeans\"]\n\nfigure = plt.figure(figsize=(14, 9))\ni = 1\nfor ds_cnt, X in enumerate(X_list):\n    ax = plt.subplot(len(X_list), len(strategies) + 1, i)\n    ax.scatter(X[:, 0], X[:, 1], edgecolors=\"k\")\n    if ds_cnt == 0:\n        ax.set_title(\"Input data\", size=14)\n\n    xx, yy = np.meshgrid(\n        np.linspace(X[:, 0].min(), X[:, 0].max(), 300),\n        np.linspace(X[:, 1].min(), X[:, 1].max(), 300),\n    )\n    grid = np.c_[xx.ravel(), yy.ravel()]\n\n    ax.set_xlim(xx.min(), xx.max())\n    ax.set_ylim(yy.min(), yy.max())\n    ax.set_xticks(())\n    ax.set_yticks(())\n\n    i += 1\n    # transform the dataset with KBinsDiscretizer\n    for strategy in strategies:\n        enc = KBinsDiscretizer(n_bins=4, encode=\"ordinal\", strategy=strategy)\n        enc.fit(X)\n        grid_encoded = enc.transform(grid)\n\n        ax = plt.subplot(len(X_list), len(strategies) + 1, i)\n\n        # horizontal stripes\n        horizontal = grid_encoded[:, 0].reshape(xx.shape)\n        ax.contourf(xx, yy, horizontal, alpha=0.5)\n        # vertical stripes\n        vertical = grid_encoded[:, 1].reshape(xx.shape)\n        ax.contourf(xx, yy, vertical, alpha=0.5)\n\n        ax.scatter(X[:, 0], X[:, 1], edgecolors=\"k\")\n        ax.set_xlim(xx.min(), xx.max())\n        ax.set_ylim(yy.min(), yy.max())\n        ax.set_xticks(())\n        ax.set_yticks(())\n        if ds_cnt == 0:\n            ax.set_title(\"strategy='%s'\" % (strategy,), size=14)\n\n        i += 1\n\nplt.tight_layout()"}]},{"title":"Visualize Results","body":["We will now visualize the results of applying the different strategies to the datasets. The plots show the regions where the discretized encoding is constant."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-creating-visualizations-with-display-objects":{"intro":"In this lab, we will learn how to create visualizations with display objects using scikit-learn. Display objects are classes that allow us to create visualizations directly from their respective metrics. In this lab, we will use the ConfusionMatrixDisplay, RocCurveDisplay, and PrecisionRecallDisplay display objects to create visualizations for a binary classification problem.","steps":[{"title":"Load Data and Train Model","body":["For this example, we will use a blood transfusion service center dataset from OpenML. The target is whether an individual donated blood. First, the data is split into training and test datasets, and then a logistic regression model is fitted with the training dataset."],"code":[{"lang":"python","text":"from sklearn.datasets import fetch_openml\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.model_selection import train_test_split\n\nX, y = fetch_openml(data_id=1464, return_X_y=True, parser=\"pandas\")\nX_train, X_test, y_train, y_test = train_test_split(X, y, stratify=y)\n\nclf = make_pipeline(StandardScaler(), LogisticRegression(random_state=0))\nclf.fit(X_train, y_train)"}]},{"title":"Create ConfusionMatrixDisplay","body":["With the fitted model, we compute the predictions of the model on the test dataset. These predictions are used to compute the confusion matrix which is plotted with the ConfusionMatrixDisplay."],"code":[{"lang":"python","text":"from sklearn.metrics import confusion_matrix\nfrom sklearn.metrics import ConfusionMatrixDisplay\n\ny_pred = clf.predict(X_test)\ncm = confusion_matrix(y_test, y_pred)\n\ncm_display = ConfusionMatrixDisplay(cm).plot()"}]},{"title":"Create RocCurveDisplay","body":["The ROC curve requires either the probabilities or the non-thresholded decision values from the estimator. Since the logistic regression provides a decision function, we will use it to plot the ROC curve."],"code":[{"lang":"python","text":"from sklearn.metrics import roc_curve\nfrom sklearn.metrics import RocCurveDisplay\n\ny_score = clf.decision_function(X_test)\n\nfpr, tpr, _ = roc_curve(y_test, y_score, pos_label=clf.classes_[1])\nroc_display = RocCurveDisplay(fpr=fpr, tpr=tpr).plot()"}]},{"title":"Create PrecisionRecallDisplay","body":["Similarly, the precision-recall curve can be plotted using y_score from the previous section."],"code":[{"lang":"python","text":"from sklearn.metrics import precision_recall_curve\nfrom sklearn.metrics import PrecisionRecallDisplay\n\nprec, recall, _ = precision_recall_curve(y_test, y_score, pos_label=clf.classes_[1])\npr_display = PrecisionRecallDisplay(precision=prec, recall=recall).plot()"}]},{"title":"Combine Display Objects into a Single Plot","body":["Combine Display Objects into a Single Plot","The display objects store the computed values that were passed as arguments. This allows for the visualizations to be easily combined using Matplotlib's API. In the following example, we place the displays next to each other in a row."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 8))\n\nroc_display.plot(ax=ax1)\npr_display.plot(ax=ax2)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 8))\n\nroc_display.plot(ax=ax1)\npr_display.plot(ax=ax2)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-text-document-classification":{"intro":"This lab demonstrates how to use scikit-learn to classify text documents into different categories. We will use the 20 newsgroups dataset, which contains around 18,000 newsgroup posts on 20 topics. We will use a bag of words approach and a Tf-idf-weighted document-term sparse matrix to encode the features. The lab will also demonstrate various classifiers that can efficiently handle sparse matrices.","steps":[{"title":"Loading and Vectorizing the 20 Newsgroups Text Dataset","body":["Loading and Vectorizing the 20 Newsgroups Text Dataset","We define a function to load data from 20newsgroups_dataset, which comprises around 18,000 newsgroups posts on 20 topics split into two subsets: one for training and the other one for testing. We will load and vectorize the dataset without metadata stripping."],"code":[{"lang":"python","text":"from sklearn.datasets import fetch_20newsgroups\nfrom sklearn.feature_extraction.text import TfidfVectorizer\n\ncategories = [\n    \"alt.atheism\",\n    \"talk.religion.misc\",\n    \"comp.graphics\",\n    \"sci.space\",\n]\n\ndef load_dataset(verbose=False, remove=()):\n    \"\"\"Load and vectorize the 20 newsgroups dataset.\"\"\"\n    data_train = fetch_20newsgroups(\n        subset=\"train\",\n        categories=categories,\n        shuffle=True,\n        random_state=42,\n        remove=remove,\n    )\n\n    data_test = fetch_20newsgroups(\n        subset=\"test\",\n        categories=categories,\n        shuffle=True,\n        random_state=42,\n        remove=remove,\n    )\n\n    # order of labels in `target_names` can be different from `categories`\n    target_names = data_train.target_names\n\n    # split target in a training set and a test set\n    y_train, y_test = data_train.target, data_test.target\n\n    # Extracting features from the training data using a sparse vectorizer\n    vectorizer = TfidfVectorizer(\n        sublinear_tf=True, max_df=0.5, min_df=5, stop_words=\"english\"\n    )\n    X_train = vectorizer.fit_transform(data_train.data)\n\n    # Extracting features from the test data using the same vectorizer\n    X_test = vectorizer.transform(data_test.data)\n\n    feature_names = vectorizer.get_feature_names_out()\n\n    if verbose:\n        print(f\"{len(data_train.data)} documents\")\n        print(f\"{len(data_test.data)} documents\")"}]},{"title":"Analysis of a Bag-of-Words Document Classifier","body":["Analysis of a Bag-of-Words Document Classifier","We will now train a classifier twice, once on the text samples including metadata and once after stripping the metadata. We will analyze the classification errors on a test set using a confusion matrix and inspect the coefficients that define the classification function of the trained models."],"code":[{"lang":"python","text":"from sklearn.linear_model import RidgeClassifier\nfrom sklearn.metrics import ConfusionMatrixDisplay\nimport matplotlib.pyplot as plt\nimport pandas as pd\nimport numpy as np\n\nclf = RidgeClassifier(tol=1e-2, solver=\"sparse_cg\")\nclf.fit(X_train, y_train)\npred = clf.predict(X_test)\n\nfig, ax = plt.subplots(figsize=(10, 5))\nConfusionMatrixDisplay.from_predictions(y_test, pred, ax=ax)\nax.xaxis.set_ticklabels(target_names)\nax.yaxis.set_ticklabels(target_names)\n_ = ax.set_title(\n    f\"Confusion Matrix for {clf.__class__.__name__}\\non the original documents\"\n)\n\ndef plot_feature_effects():\n    # learned coefficients weighted by frequency of appearance\n    average_feature_effects = clf.coef_ * np.asarray(X_train.mean(axis=0)).ravel()\n\n    for i, label in enumerate(target_names):\n        top5 = np.argsort(average_feature_effects[i])[-5:][::-1]\n        if i == 0:\n            top = pd.DataFrame(feature_names[top5], columns=[label])\n            top_indices = top5\n        else:\n            top[label] = feature_names[top5]\n            top_indices = np.concatenate((top_indices, top5), axis=None)\n    top_indices = np.unique(top_indices)\n    predictive_words = feature_names[top_indices]\n\n    # plot feature effects\n    bar_size = 0.25\n    padding = 0.75\n    y_locs = np.arange(len(top_indices)) * (4 * bar_size + padding)\n\n    fig, ax = plt.subplots(figsize=(10, 8))\n    for i, label in enumerate(target_names):\n        ax.barh(\n            y_locs + (i - 2) * bar_size,\n            average_feature_effects[i, top_indices],\n            height=bar_size,\n            label=label,\n        )\n    ax.set(\n        yticks=y_locs,"}]},{"title":"Model with Metadata Stripping","body":["We will now use the remove option of the 20 newsgroups dataset loader in scikit-learn to train a text classifier that does not rely too much on metadata to make its decisions. We will also analyze the classification errors on a test set using a confusion matrix and inspect the coefficients that define the classification function of the trained models."],"code":[{"lang":"python","text":"(\n    X_train,\n    X_test,\n    y_train,\n    y_test,\n    feature_names,\n    target_names,\n) = load_dataset(remove=(\"headers\", \"footers\", \"quotes\"))\n\nclf = RidgeClassifier(tol=1e-2, solver=\"sparse_cg\")\nclf.fit(X_train, y_train)\npred = clf.predict(X_test)\n\nfig, ax = plt.subplots(figsize=(10, 5))\nConfusionMatrixDisplay.from_predictions(y_test, pred, ax=ax)\nax.xaxis.set_ticklabels(target_names)\nax.yaxis.set_ticklabels(target_names)\n_ = ax.set_title(\n    f\"Confusion Matrix for {clf.__class__.__name__}\\non filtered documents\"\n)\n\n_ = plot_feature_effects().set_title(\"Average feature effects on filtered documents\")"}]},{"title":"Benchmarking Classifiers","body":["We will now train and test the datasets with eight different classification models and get performance results for each model. The goal of this study is to highlight the computation/accuracy tradeoffs of different types of classifiers for such a multi-class text classification problem."],"code":[{"lang":"python","text":"from sklearn.utils.extmath import density\nfrom sklearn import metrics\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.svm import LinearSVC\nfrom sklearn.linear_model import SGDClassifier\nfrom sklearn.naive_bayes import ComplementNB\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.neighbors import NearestCentroid\nfrom sklearn.ensemble import RandomForestClassifier\n\nresults = []\nfor clf, name in (\n    (LogisticRegression(C=5, max_iter=1000), \"Logistic Regression\"),\n    (RidgeClassifier(alpha=1.0, solver=\"sparse_cg\"), \"Ridge Classifier\"),\n    (KNeighborsClassifier(n_neighbors=100), \"kNN\"),\n    (RandomForestClassifier(), \"Random Forest\"),\n    # L2 penalty Linear SVC\n    (LinearSVC(C=0.1, dual=False, max_iter=1000), \"Linear SVC\"),\n    # L2 penalty Linear SGD\n    (\n        SGDClassifier(\n            loss=\"log_loss\", alpha=1e-4, n_iter_no_change=3, early_stopping=True\n        ),\n        \"log-loss SGD\",\n    ),\n    # NearestCentroid (aka Rocchio classifier)\n    (NearestCentroid(), \"NearestCentroid\"),\n    # Sparse naive Bayes classifier\n    (ComplementNB(alpha=0.1), \"Complement naive Bayes\"),\n):\n    print(\"=\" * 80)\n    print(name)\n    results.append(benchmark(clf, name))\n\nindices = np.arange(len(results))\n\nresults = [[x[i] for x in results] for i in range(4)]\n\nclf_names, score, training_time, test_time = results\ntraining_time = np.array(training_time)\ntest_time = np.array(test_time)\n\nfig, ax1 = plt.subplots(figsize=(10, 8))\nax1.scatter(score, training_time, s=60)\nax1.set(\n    title=\"Score-training time trade-off\",\n    yscale=\"log\",\n    xlabel=\"test accuracy\","}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.utils.extmath import density\nfrom sklearn import metrics\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.svm import LinearSVC\nfrom sklearn.linear_model import SGDClassifier\nfrom sklearn.naive_bayes import ComplementNB\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.neighbors import NearestCentroid\nfrom sklearn.ensemble import RandomForestClassifier\n\nresults = []\nfor clf, name in (\n    (LogisticRegression(C=5, max_iter=1000), \"Logistic Regression\"),\n    (RidgeClassifier(alpha=1.0, solver=\"sparse_cg\"), \"Ridge Classifier\"),\n    (KNeighborsClassifier(n_neighbors=100), \"kNN\"),\n    (RandomForestClassifier(), \"Random Forest\"),\n    # L2 penalty Linear SVC\n    (LinearSVC(C=0.1, dual=False, max_iter=1000), \"Linear SVC\"),\n    # L2 penalty Linear SGD\n    (\n        SGDClassifier(\n            loss=\"log_loss\", alpha=1e-4, n_iter_no_change=3, early_stopping=True\n        ),\n        \"log-loss SGD\",\n    ),\n    # NearestCentroid (aka Rocchio classifier)\n    (NearestCentroid(), \"NearestCentroid\"),\n    # Sparse naive Bayes classifier\n    (ComplementNB(alpha=0.1), \"Complement naive Bayes\"),\n):\n    print(\"=\" * 80)\n    print(name)\n    results.append(benchmark(clf, name))\n\nindices = np.arange(len(results))\n\nresults = [[x[i] for x in results] for i in range(4)]\n\nclf_names, score, training_time, test_time = results\ntraining_time = np.array(training_time)\ntest_time = np.array(test_time)\n\nfig, ax1 = plt.subplots(figsize=(10, 8))\nax1.scatter(score, training_time, s=60)\nax1.set(\n    title=\"Score-training time trade-off\",\n    yscale=\"log\",\n    xlabel=\"test accuracy\","}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-precompute-gram-matrix-for-elasticnet":{"intro":"This lab demonstrates how to precompute the gram matrix while using weighted samples with an ElasticNet. It is important to note that if weighted samples are used, the design matrix must be centered and then rescaled by the square root of the weight vector before the gram matrix is computed.","steps":[{"title":"Loading the Dataset and Creating Sample Weights","body":["Loading the Dataset and Creating Sample Weights","We start by loading the dataset and creating some sample weights. We use the make_regression function from scikit-learn to generate a random regression dataset with 100,000 samples. Then, we generate a lognormal weight vector and normalize it to sum to the total number of samples."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import make_regression\n\nrng = np.random.RandomState(0)\n\nn_samples = int(1e5)\nX, y = make_regression(n_samples=n_samples, noise=0.5, random_state=rng)\n\nsample_weight = rng.lognormal(size=n_samples)\n# normalize the sample weights\nnormalized_weights = sample_weight * (n_samples / (sample_weight.sum()))"}]},{"title":"Precomputing Gram Matrix with Weighted Samples","body":["Precomputing Gram Matrix with Weighted Samples","To fit the elastic net using the precompute option together with the sample weights, we must first center the design matrix and rescale it by the normalized weights prior to computing the gram matrix. We center the design matrix by subtracting the weighted average of each feature column from each row. Then, we rescale the centered design matrix by multiplying each row with the square root of the corresponding normalized weight. Finally, we compute the gram matrix by taking the dot product of the rescaled design matrix with its transpose."],"code":[{"lang":"python","text":"X_offset = np.average(X, axis=0, weights=normalized_weights)\nX_centered = X - np.average(X, axis=0, weights=normalized_weights)\nX_scaled = X_centered * np.sqrt(normalized_weights)[:, np.newaxis]\ngram = np.dot(X_scaled.T, X_scaled)"}]},{"title":"Fitting the Elastic Net","body":["We can now proceed with fitting. We must pass the centered design matrix to fit to prevent the elastic net estimator from detecting that it is uncentered and discarding the gram matrix we passed. However, if we pass the scaled design matrix, the preprocessing code will incorrectly rescale it a second time. We also pass the normalized weights to the sample_weight parameter of the fit function."],"code":[{"lang":"python","text":"from sklearn.linear_model import ElasticNet\n\nlm = ElasticNet(alpha=0.01, precompute=gram)\nlm.fit(X_centered, y, sample_weight=normalized_weights)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.linear_model import ElasticNet\n\nlm = ElasticNet(alpha=0.01, precompute=gram)\nlm.fit(X_centered, y, sample_weight=normalized_weights)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-random-forest-oob-error-estimation":{"intro":"In this lab, we will demonstrate how to measure the Out-Of-Bag (OOB) error rate for a Random Forest model using the Python scikit-learn library. The OOB error rate is the average error for each training observation calculated using predictions from the trees that do not contain the observation in their respective bootstrap sample. This allows the Random Forest model to be fit and validated while being trained.","steps":[{"title":"Import Required Libraries","body":["We will begin by importing the required libraries, including scikit-learn, NumPy, and Matplotlib. We will also set a random state value to ensure reproducibility."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom collections import OrderedDict\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import RandomForestClassifier\n\nRANDOM_STATE = 123"}]},{"title":"Generate a Binary Classification Dataset","body":["Generate a Binary Classification Dataset","Next, we will generate a binary classification dataset using the make_classification function provided by scikit-learn. This function allows us to specify the number of samples, features, clusters per class, and informative features. We will use a fixed random state value to ensure reproducibility."],"code":[{"lang":"python","text":"X, y = make_classification(\n    n_samples=500,\n    n_features=25,\n    n_clusters_per_class=1,\n    n_informative=15,\n    random_state=RANDOM_STATE,\n)"}]},{"title":"Define the Ensemble Classifiers","body":["Define the Ensemble Classifiers","We will define a list of three Random Forest classifiers, each with a different value for the max_features parameter. We will set the warm_start construction parameter to True to enable tracking of the OOB error rate during training. We will also set the oob_score parameter to True to enable OOB error rate calculation."],"code":[{"lang":"python","text":"ensemble_clfs = [\n    (\n        \"RandomForestClassifier, max_features='sqrt'\",\n        RandomForestClassifier(\n            warm_start=True,\n            oob_score=True,\n            max_features=\"sqrt\",\n            random_state=RANDOM_STATE,\n        ),\n    ),\n    (\n        \"RandomForestClassifier, max_features='log2'\",\n        RandomForestClassifier(\n            warm_start=True,\n            max_features=\"log2\",\n            oob_score=True,\n            random_state=RANDOM_STATE,\n        ),\n    ),\n    (\n        \"RandomForestClassifier, max_features=None\",\n        RandomForestClassifier(\n            warm_start=True,\n            max_features=None,\n            oob_score=True,\n            random_state=RANDOM_STATE,\n        ),\n    ),\n]"}]},{"title":"Calculate the OOB Error Rate","body":["For each classifier, we will loop through a range of n_estimators values and fit the classifier to the dataset. We will record the OOB error rate for each n_estimators value and store it in an OrderedDict object."],"code":[{"lang":"python","text":"error_rate = OrderedDict((label, []) for label, _ in ensemble_clfs)\n\nmin_estimators = 15\nmax_estimators = 150\n\nfor label, clf in ensemble_clfs:\n    for i in range(min_estimators, max_estimators + 1, 5):\n        clf.set_params(n_estimators=i)\n        clf.fit(X, y)\n\n        oob_error = 1 - clf.oob_score_\n        error_rate[label].append((i, oob_error))"}]},{"title":"Visualize the OOB Error Rate","body":["Finally, we will plot the OOB error rate for each classifier as a function of the number of estimators. This will allow us to identify the number of estimators at which the error rate stabilizes. We will use Matplotlib to generate the plot."],"code":[{"lang":"python","text":"for label, clf_err in error_rate.items():\n    xs, ys = zip(*clf_err)\n    plt.plot(xs, ys, label=label)\n\nplt.xlim(min_estimators, max_estimators)\nplt.xlabel(\"n_estimators\")\nplt.ylabel(\"OOB error rate\")\nplt.legend(loc=\"upper right\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"for label, clf_err in error_rate.items():\n    xs, ys = zip(*clf_err)\n    plt.plot(xs, ys, label=label)\n\nplt.xlim(min_estimators, max_estimators)\nplt.xlabel(\"n_estimators\")\nplt.ylabel(\"OOB error rate\")\nplt.legend(loc=\"upper right\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-comparison-of-f-test-and-mutual-information":{"intro":"In this lab, we will learn about the differences between univariate F-test statistics and mutual information. We will use scikit-learn library to perform F-test and mutual information regression on a dataset and compare the results.","steps":[{"title":"Import libraries","body":["We will start by importing the necessary libraries for this lab. We will use numpy, matplotlib and scikit-learn for this lab."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn.feature_selection import f_regression, mutual_info_regression"}]},{"title":"Create dataset","body":["We will create a dataset with 3 features, where the first feature has a linear relationship with the target, the second feature has a non-linear relationship with the target, and the third feature is completely irrelevant. We will create 1000 samples for this dataset."],"code":[{"lang":"python","text":"np.random.seed(0)\nX = np.random.rand(1000, 3)\ny = X[:, 0] + np.sin(6 * np.pi * X[:, 1]) + 0.1 * np.random.randn(1000)"}]},{"title":"Calculate F-test","body":["We will now calculate the F-test score for each feature. F-test captures only linear dependency between variables. We will normalize the F-test scores by dividing them by the maximum F-test score."],"code":[{"lang":"python","text":"f_test, _ = f_regression(X, y)\nf_test /= np.max(f_test)"}]},{"title":"Calculate mutual information","body":["We will now calculate the mutual information score for each feature. Mutual information can capture any kind of dependency between variables. We will normalize the mutual information scores by dividing them by the maximum mutual information score."],"code":[{"lang":"python","text":"mi = mutual_info_regression(X, y)\nmi /= np.max(mi)"}]},{"title":"Plot the results","body":["We will now plot the dependency of the target against each feature and the F-test and mutual information scores for each feature."],"code":[{"lang":"python","text":"plt.figure(figsize=(15, 5))\nfor i in range(3):\n    plt.subplot(1, 3, i + 1)\n    plt.scatter(X[:, i], y, edgecolor=\"black\", s=20)\n    plt.xlabel(\"$x_{}$\".format(i + 1), fontsize=14)\n    if i == 0:\n        plt.ylabel(\"$y$\", fontsize=14)\n    plt.title(\"F-test={:.2f}, MI={:.2f}\".format(f_test[i], mi[i]), fontsize=16)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(figsize=(15, 5))\nfor i in range(3):\n    plt.subplot(1, 3, i + 1)\n    plt.scatter(X[:, i], y, edgecolor=\"black\", s=20)\n    plt.xlabel(\"$x_{}$\".format(i + 1), fontsize=14)\n    if i == 0:\n        plt.ylabel(\"$y$\", fontsize=14)\n    plt.title(\"F-test={:.2f}, MI={:.2f}\".format(f_test[i], mi[i]), fontsize=16)\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-vector-quantization-with-kbinsdiscretizer":{"intro":"This lab demonstrates how to use KBinsDiscretizer from the Scikit-learn library to perform vector quantization on a sample image of a raccoon face. Vector quantization is a technique to reduce the number of gray levels used to represent an image. We will use KBinsDiscretizer to perform vector quantization on the raccoon face image. We will use 8 gray levels to represent the image, which can be compressed to use only 3 bits per pixel. We will compare the uniform and k-means clustering strategies to map the pixel values to the 8 gray levels.","steps":[{"title":"Load and Display the Original Image","body":["Load and Display the Original Image","We will start by loading the raccoon face image from Scipy. We will display the image and check its shape, data type, and memory usage."],"code":[{"lang":"python","text":"from scipy.misc import face\nimport matplotlib.pyplot as plt\n\nraccoon_face = face(gray=True)\n\nprint(f\"The dimension of the image is {raccoon_face.shape}\")\nprint(f\"The data used to encode the image is of type {raccoon_face.dtype}\")\nprint(f\"The number of bytes taken in RAM is {raccoon_face.nbytes}\")\n\nfig, ax = plt.subplots(ncols=2, figsize=(12, 4))\nax[0].imshow(raccoon_face, cmap=plt.cm.gray)\nax[0].axis(\"off\")\nax[0].set_title(\"Original Image\")\nax[1].hist(raccoon_face.ravel(), bins=256)\nax[1].set_xlabel(\"Pixel value\")\nax[1].set_ylabel(\"Count of pixels\")\nax[1].set_title(\"Distribution of the pixel values\")\n_ = fig.suptitle(\"Original Image of a Raccoon Face\")"}]},{"title":"Vector Quantization using KBinsDiscretizer","body":["Vector Quantization using KBinsDiscretizer","We will now use KBinsDiscretizer to perform vector quantization on the raccoon face image. We will use 8 gray levels to represent the image, which can be compressed to use only 3 bits per pixel. We will use the uniform and k-means clustering strategies to map the pixel values to the 8 gray levels.","We will first use the uniform sampling strategy to map the pixel values to the 8 gray levels.","We will now use the k-means clustering strategy to map the pixel values to the 8 gray levels."],"code":[{"lang":"python","text":"from sklearn.preprocessing import KBinsDiscretizer\n\nn_bins = 8\nencoder = KBinsDiscretizer(\n    n_bins=n_bins, encode=\"ordinal\", strategy=\"uniform\", random_state=0\n)\ncompressed_raccoon_uniform = encoder.fit_transform(raccoon_face.reshape(-1, 1)).reshape(\n    raccoon_face.shape\n)\n\nfig, ax = plt.subplots(ncols=2, figsize=(12, 4))\nax[0].imshow(compressed_raccoon_uniform, cmap=plt.cm.gray)\nax[0].axis(\"off\")\nax[0].set_title(\"Uniform Sampling\")\nax[1].hist(compressed_raccoon_uniform.ravel(), bins=256)\nax[1].set_xlabel(\"Pixel value\")\nax[1].set_ylabel(\"Count of pixels\")\nax[1].set_title(\"Distribution of the pixel values\")\n_ = fig.suptitle(\"Raccoon face compressed using 3 bits and a uniform strategy\")"},{"lang":"python","text":"encoder = KBinsDiscretizer(\n    n_bins=n_bins, encode=\"ordinal\", strategy=\"kmeans\", random_state=0\n)\ncompressed_raccoon_kmeans = encoder.fit_transform(raccoon_face.reshape(-1, 1)).reshape(\n    raccoon_face.shape\n)\n\nfig, ax = plt.subplots(ncols=2, figsize=(12, 4))\nax[0].imshow(compressed_raccoon_kmeans, cmap=plt.cm.gray)\nax[0].axis(\"off\")\nax[0].set_title(\"K-Means Clustering\")\nax[1].hist(compressed_raccoon_kmeans.ravel(), bins=256)\nax[1].set_xlabel(\"Pixel value\")\nax[1].set_ylabel(\"Count of pixels\")\nax[1].set_title(\"Distribution of the pixel values\")\n_ = fig.suptitle(\"Raccoon face compressed using 3 bits and a K-means strategy\")"}]},{"title":"Memory Footprint","body":["We will now check the memory usage of the compressed images. We expect the compressed image to take 8 times less memory than the original image."],"code":[{"lang":"python","text":"print(f\"The number of bytes taken in RAM is {compressed_raccoon_kmeans.nbytes}\")\nprint(f\"Compression ratio: {compressed_raccoon_kmeans.nbytes / raccoon_face.nbytes}\")"}]},{"title":"Summary","body":["In this lab, we used KBinsDiscretizer from Scikit-learn to perform vector quantization on a sample image of a raccoon face. We used 8 gray levels to represent the image, which can be compressed to use only 3 bits per pixel. We compared the uniform and k-means clustering strategies to map the pixel values to the 8 gray levels. We found that the k-means clustering strategy provided a more balanced distribution of the pixel values. We also checked the memory usage of the compressed images and found that the compressed image took 8 times more memory than the original image due to the use of a 64-bit float representation for the…"],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-face-recognition-with-eigenfaces-and-svms":{"intro":"This lab will guide you through the steps to perform face recognition using eigenfaces and Support Vector Machines (SVMs). The dataset used in this lab is a preprocessed excerpt of the 'Labeled Faces in the Wild' dataset.","steps":[{"title":"Import Libraries","body":["First, we need to import all the necessary libraries."],"code":[{"lang":"python","text":"from time import time\nimport matplotlib.pyplot as plt\n\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.model_selection import RandomizedSearchCV\nfrom sklearn.datasets import fetch_lfw_people\nfrom sklearn.metrics import classification_report\nfrom sklearn.metrics import ConfusionMatrixDisplay\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.decomposition import PCA\nfrom sklearn.svm import SVC\nfrom scipy.stats import loguniform"}]},{"title":"Load and Explore Dataset","body":["We download the dataset using the fetch_lfw_people() function from scikit-learn. We then explore the dataset by getting the number of samples, height, and width of the images. We also get the input data X, target y, target names target_names, and number of classes n_classes."],"code":[{"lang":"python","text":"lfw_people = fetch_lfw_people(min_faces_per_person=70, resize=0.4)\nn_samples, h, w = lfw_people.images.shape\nX = lfw_people.data\nn_features = X.shape[1]\ny = lfw_people.target\ntarget_names = lfw_people.target_names\nn_classes = target_names.shape[0]"}]},{"title":"Data Preprocessing","body":["We split the dataset into a training set and a test set and preprocess the data by scaling the input data using the StandardScaler() function."],"code":[{"lang":"python","text":"X_train, X_test, y_train, y_test = train_test_split(\n    X, y, test_size=0.25, random_state=42\n)\nscaler = StandardScaler()\nX_train = scaler.fit_transform(X_train)\nX_test = scaler.transform(X_test)"}]},{"title":"Perform PCA","body":["We perform Principal Component Analysis (PCA) to extract features from the input data. We set the number of components to 150 and fit the PCA model to the training data. We then get the eigenfaces and transform the input data into principal components."],"code":[{"lang":"python","text":"n_components = 150\n\npca = PCA(n_components=n_components, svd_solver=\"randomized\", whiten=True).fit(X_train)\neigenfaces = pca.components_.reshape((n_components, h, w))\n\nX_train_pca = pca.transform(X_train)\nX_test_pca = pca.transform(X_test)"}]},{"title":"Train a Support Vector Machine (SVM) Classification Model","body":["Train a Support Vector Machine (SVM) Classification Model","We train a SVM classification model using the transformed data. We use RandomizedSearchCV() to find the best hyperparameters for the SVM model."],"code":[{"lang":"python","text":"param_grid = {\n    \"C\": loguniform(1e3, 1e5),\n    \"gamma\": loguniform(1e-4, 1e-1),\n}\n\nclf = RandomizedSearchCV(\n    SVC(kernel=\"rbf\", class_weight=\"balanced\"), param_grid, n_iter=10\n)\nclf = clf.fit(X_train_pca, y_train)"}]},{"title":"Evaluate Model Performance","body":["We predict the target values using the test data and evaluate the model performance using the classification_report() function. We also plot the confusion matrix using the ConfusionMatrixDisplay() function."],"code":[{"lang":"python","text":"y_pred = clf.predict(X_test_pca)\nprint(classification_report(y_test, y_pred, target_names=target_names))\nConfusionMatrixDisplay.from_estimator(\n    clf, X_test_pca, y_test, display_labels=target_names, xticks_rotation=\"vertical\"\n)"}]},{"title":"Visualize Predictions","body":["We visualize the predictions by plotting a gallery of portraits with their predicted and true names."],"code":[{"lang":"python","text":"def plot_gallery(images, titles, h, w, n_row=3, n_col=4):\n    \"\"\"Helper function to plot a gallery of portraits\"\"\"\n    plt.figure(figsize=(1.8 * n_col, 2.4 * n_row))\n    plt.subplots_adjust(bottom=0, left=0.01, right=0.99, top=0.90, hspace=0.35)\n    for i in range(n_row * n_col):\n        plt.subplot(n_row, n_col, i + 1)\n        plt.imshow(images[i].reshape((h, w)), cmap=plt.cm.gray)\n        plt.title(titles[i], size=12)\n        plt.xticks(())\n        plt.yticks(())\n\nprediction_titles = [\n    title(y_pred, y_test, target_names, i) for i in range(y_pred.shape[0])\n]\n\nplot_gallery(X_test, prediction_titles, h, w)"}]},{"title":"Visualize Eigenfaces","body":["We also plot the eigenfaces to visualize the features extracted from the input data."],"code":[{"lang":"python","text":"eigenface_titles = [\"eigenface %d\" % i for i in range(eigenfaces.shape[0])]\nplot_gallery(eigenfaces, eigenface_titles, h, w)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"eigenface_titles = [\"eigenface %d\" % i for i in range(eigenfaces.shape[0])]\nplot_gallery(eigenfaces, eigenface_titles, h, w)\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-faces-dataset-decompositions":{"intro":"This lab applies different unsupervised matrix decomposition (dimension reduction) methods from the module sklearn.decomposition to the Olivetti faces dataset. The Olivetti faces dataset consists of 400 faces of size 64x64 pixels from 40 individuals, each captured with different facial expressions and lighting conditions.","steps":[{"title":"Dataset Preparation","body":["First, we load and preprocess the Olivetti faces dataset. We center the data to have zero mean, both globally (focus on one feature, centering all samples) and locally (focus on one sample, centering all features). We also define a base function to plot the gallery of faces."],"code":[{"lang":"python","text":"# Loading and preprocessing the Olivetti faces dataset.\n\nimport logging\n\nfrom numpy.random import RandomState\nimport matplotlib.pyplot as plt\n\nfrom sklearn.datasets import fetch_olivetti_faces\nfrom sklearn import cluster\nfrom sklearn import decomposition\n\nrng = RandomState(0)\n\n# Display progress logs on stdout\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s %(levelname)s %(message)s\")\n\nfaces, _ = fetch_olivetti_faces(return_X_y=True, shuffle=True, random_state=rng)\nn_samples, n_features = faces.shape\n\n# Global centering (focus on one feature, centering all samples)\nfaces_centered = faces - faces.mean(axis=0)\n\n# Local centering (focus on one sample, centering all features)\nfaces_centered -= faces_centered.mean(axis=1).reshape(n_samples, -1)\n\nprint(\"Dataset consists of %d faces\" % n_samples)\n\n# Define a base function to plot the gallery of faces.\n\nn_row, n_col = 2, 3\nn_components = n_row * n_col\nimage_shape = (64, 64)\n\n\ndef plot_gallery(title, images, n_col=n_col, n_row=n_row, cmap=plt.cm.gray):\n    fig, axs = plt.subplots(\n        nrows=n_row,\n        ncols=n_col,\n        figsize=(2.0 * n_col, 2.3 * n_row),\n        facecolor=\"white\",\n        constrained_layout=True,\n    )\n    fig.set_constrained_layout_pads(w_pad=0.01, h_pad=0.02, hspace=0, wspace=0)\n    fig.set_edgecolor(\"black\")\n    fig.suptitle(title, size=16)\n    for ax, vec in zip(axs.flat, images):\n        vmax = max(vec.max(), -vec.min())\n        im = ax.imshow("}]},{"title":"Eigenfaces - PCA using randomized SVD","body":["Eigenfaces - PCA using randomized SVD","The first method we apply is PCA, which is a linear dimensionality reduction technique that uses Singular Value Decomposition (SVD) of the data to project it to a lower dimensional space. We use randomized SVD, which is a faster approximation of the standard SVD algorithm. We plot the first six principal components, which are called eigenfaces."],"code":[{"lang":"python","text":"# Eigenfaces - PCA using randomized SVD\npca_estimator = decomposition.PCA(\n    n_components=n_components, svd_solver=\"randomized\", whiten=True\n)\npca_estimator.fit(faces_centered)\nplot_gallery(\n    \"Eigenfaces - PCA using randomized SVD\", pca_estimator.components_[:n_components]\n)"}]},{"title":"Non-negative components - NMF","body":["Next, we apply Non-negative Matrix Factorization (NMF), which factorizes the data matrix into two non-negative matrices, one containing the basis vectors and the other containing the coefficients. This results in a parts-based representation of the data."],"code":[{"lang":"python","text":"# Non-negative components - NMF\nnmf_estimator = decomposition.NMF(n_components=n_components, tol=5e-3)\nnmf_estimator.fit(faces)  # original non- negative dataset\nplot_gallery(\"Non-negative components - NMF\", nmf_estimator.components_[:n_components])"}]},{"title":"Independent components - FastICA","body":["Independent components - FastICA","Independent Component Analysis (ICA) is a method for separating multivariate signals into additive subcomponents that are maximally independent. We apply FastICA, which is a fast and robust algorithm for ICA."],"code":[{"lang":"python","text":"# Independent components - FastICA\nica_estimator = decomposition.FastICA(\n    n_components=n_components, max_iter=400, whiten=\"arbitrary-variance\", tol=15e-5\n)\nica_estimator.fit(faces_centered)\nplot_gallery(\n    \"Independent components - FastICA\", ica_estimator.components_[:n_components]\n)"}]},{"title":"Sparse components - MiniBatchSparsePCA","body":["Sparse components - MiniBatchSparsePCA","Sparse PCA is a variant of PCA that encourages sparsity in the loading vectors, resulting in a more interpretable decomposition. We use MiniBatchSparsePCA, which is a faster version of SparsePCA that is better suited for large datasets."],"code":[{"lang":"python","text":"# Sparse components - MiniBatchSparsePCA\nbatch_pca_estimator = decomposition.MiniBatchSparsePCA(\n    n_components=n_components, alpha=0.1, max_iter=100, batch_size=3, random_state=rng\n)\nbatch_pca_estimator.fit(faces_centered)\nplot_gallery(\n    \"Sparse components - MiniBatchSparsePCA\",\n    batch_pca_estimator.components_[:n_components],\n)"}]},{"title":"Dictionary learning","body":["Dictionary learning is a method for finding a sparse representation of the input data as a combination of simple elements, which form a dictionary. We apply MiniBatchDictionaryLearning, which is a faster version of DictionaryLearning that is better suited for large datasets."],"code":[{"lang":"python","text":"# Dictionary learning\nbatch_dict_estimator = decomposition.MiniBatchDictionaryLearning(\n    n_components=n_components, alpha=0.1, max_iter=50, batch_size=3, random_state=rng\n)\nbatch_dict_estimator.fit(faces_centered)\nplot_gallery(\"Dictionary learning\", batch_dict_estimator.components_[:n_components])"}]},{"title":"Cluster centers - MiniBatchKMeans","body":["Cluster centers - MiniBatchKMeans","K-means clustering is a method for partitioning a dataset into clusters by minimizing the sum of squared distances between each point and the centroid of its assigned cluster. We apply MiniBatchKMeans, which is a faster version of KMeans that is better suited for large datasets."],"code":[{"lang":"python","text":"# Cluster centers - MiniBatchKMeans\nkmeans_estimator = cluster.MiniBatchKMeans(\n    n_clusters=n_components,\n    tol=1e-3,\n    batch_size=20,\n    max_iter=50,\n    random_state=rng,\n    n_init=\"auto\",\n)\nkmeans_estimator.fit(faces_centered)\nplot_gallery(\n    \"Cluster centers - MiniBatchKMeans\",\n    kmeans_estimator.cluster_centers_[:n_components],\n)"}]},{"title":"Factor Analysis components - FA","body":["Factor Analysis components - FA","Factor Analysis is a method for modeling the variance in every direction of the input space independently (heteroscedastic noise), similar to PCA but with this advantage. We apply FactorAnalysis, which is an implementation of Factor Analysis in scikit-learn."],"code":[{"lang":"python","text":"# Factor Analysis components - FA\nfa_estimator = decomposition.FactorAnalysis(n_components=n_components, max_iter=20)\nfa_estimator.fit(faces_centered)\nplot_gallery(\"Factor Analysis (FA)\", fa_estimator.components_[:n_components])\n\n# --- Pixelwise variance\nplt.figure(figsize=(3.2, 3.6), facecolor=\"white\", tight_layout=True)\nvec = fa_estimator.noise_variance_\nvmax = max(vec.max(), -vec.min())\nplt.imshow(\n    vec.reshape(image_shape),\n    cmap=plt.cm.gray,\n    interpolation=\"nearest\",\n    vmin=-vmax,\n    vmax=vmax,\n)\nplt.axis(\"off\")\nplt.title(\"Pixelwise variance from \\n Factor Analysis (FA)\", size=16, wrap=True)\nplt.colorbar(orientation=\"horizontal\", shrink=0.8, pad=0.03)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"dict_pos_estimator = decomposition.MiniBatchDictionaryLearning(\n    n_components=n_components,\n    alpha=0.1,\n    max_iter=50,\n    batch_size=3,\n    fit_algorithm=\"cd\",\n    random_state=rng,\n    positive_dict=True,\n    positive_code=True,\n)\ndict_pos_estimator.fit(faces_centered)\nplot_gallery(\n    \"Dictionary learning - positive dictionary & code\",\n    dict_pos_estimator.components_[:n_components],\n    cmap=plt.cm.RdBu,\n)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-univariate-feature-selection":{"intro":"This lab demonstrates how to use univariate feature selection to improve classification accuracy on a noisy dataset. Support vector machine (SVM) is used to classify the dataset both before and after applying univariate feature selection. For each feature, we plot the p-values for the univariate feature selection and the corresponding weights of SVMs. with this, we will compare model accuracy and examine the impact of univariate feature selection on model weights.","steps":[{"title":"Generate Sample Data","body":["First, we will generate some sample data for the demonstration. We will use the iris dataset and add some noisy data to it that is not correlated."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import load_iris\nfrom sklearn.model_selection import train_test_split\n\n# The iris dataset\nX, y = load_iris(return_X_y=True)\n\n# Some noisy data not correlated\nE = np.random.RandomState(42).uniform(0, 0.1, size=(X.shape[0], 20))\n\n# Add the noisy data to the informative features\nX = np.hstack((X, E))\n\n# Split dataset to select feature and evaluate the classifier\nX_train, X_test, y_train, y_test = train_test_split(X, y, stratify=y, random_state=0)"}]},{"title":"Univariate Feature Selection","body":["Next, we will perform univariate feature selection with F-test for feature scoring. We will use the default selection function to select the four most significant features."],"code":[{"lang":"python","text":"from sklearn.feature_selection import SelectKBest, f_classif\n\nselector = SelectKBest(f_classif, k=4)\nselector.fit(X_train, y_train)\nscores = -np.log10(selector.pvalues_)\nscores /= scores.max()"}]},{"title":"Plot Feature Univariate Score","body":["We can plot the univariate scores for each feature to see which features are significant."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nX_indices = np.arange(X.shape[-1])\nplt.figure(1)\nplt.clf()\nplt.bar(X_indices - 0.05, scores, width=0.2)\nplt.title(\"Feature univariate score\")\nplt.xlabel(\"Feature number\")\nplt.ylabel(r\"Univariate score ($-Log(p_{value})$)\")\nplt.show()"}]},{"title":"Compare with SVMs","body":["We will now compare the SVM classification accuracy with and without univariate feature selection.","Without Univariate Feature Selection","After Univariate Feature Selection"],"code":[{"lang":"python","text":"from sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import MinMaxScaler\nfrom sklearn.svm import LinearSVC\n\nclf = make_pipeline(MinMaxScaler(), LinearSVC(dual=\"auto\"))\nclf.fit(X_train, y_train)\nprint(\n    \"Classification accuracy without selecting features: {:.3f}\".format(\n        clf.score(X_test, y_test)\n    )\n)\n\nsvm_weights = np.abs(clf[-1].coef_).sum(axis=0)\nsvm_weights /= svm_weights.sum()"},{"lang":"python","text":"clf_selected = make_pipeline(\n    SelectKBest(f_classif, k=4), MinMaxScaler(), LinearSVC(dual=\"auto\")\n)\nclf_selected.fit(X_train, y_train)\nprint(\n    \"Classification accuracy after univariate feature selection: {:.3f}\".format(\n        clf_selected.score(X_test, y_test)\n    )\n)\n\nsvm_weights_selected = np.abs(clf_selected[-1].coef_).sum(axis=0)\nsvm_weights_selected /= svm_weights_selected.sum()"}]},{"title":"Plot Comparing Feature Selection","body":["Plot Comparing Feature Selection","We can plot the feature scores and weights for each feature to see the impact of univariate feature selection."],"code":[{"lang":"python","text":"plt.bar(\n    X_indices - 0.45, scores, width=0.2, label=r\"Univariate score ($-Log(p_{value})$)\"\n)\n\nplt.bar(X_indices - 0.25, svm_weights, width=0.2, label=\"SVM weight\")\n\nplt.bar(\n    X_indices[selector.get_support()] - 0.05,\n    svm_weights_selected,\n    width=0.2,\n    label=\"SVM weights after selection\",\n)\n\nplt.title(\"Comparing feature selection\")\nplt.xlabel(\"Feature number\")\nplt.yticks(())\nplt.axis(\"tight\")\nplt.legend(loc=\"upper right\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.bar(\n    X_indices - 0.45, scores, width=0.2, label=r\"Univariate score ($-Log(p_{value})$)\"\n)\n\nplt.bar(X_indices - 0.25, svm_weights, width=0.2, label=\"SVM weight\")\n\nplt.bar(\n    X_indices[selector.get_support()] - 0.05,\n    svm_weights_selected,\n    width=0.2,\n    label=\"SVM weights after selection\",\n)\n\nplt.title(\"Comparing feature selection\")\nplt.xlabel(\"Feature number\")\nplt.yticks(())\nplt.axis(\"tight\")\nplt.legend(loc=\"upper right\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-building-machine-learning-pipelines-with-sci":{"intro":"In machine learning, a pipeline is a series of steps that are performed sequentially to transform the input data and then build a model. Scikit-learn provides a pipeline class that can be used to chain multiple processing steps together, making it easy to build complex models that involve multiple preprocessing and modeling steps.","steps":[{"title":"Generate and Split the Dataset","body":["Generate and Split the Dataset","We will start by generating a binary classification dataset using Scikit-learn's make_classification function. We will also split the dataset into training and testing subsets using Scikit-learn's train_test_split function."],"code":[{"lang":"python","text":"from sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\n\nX, y = make_classification(\n    n_features=20,\n    n_informative=3,\n    n_redundant=0,\n    n_classes=2,\n    n_clusters_per_class=2,\n    random_state=42,\n)\nX_train, X_test, y_train, y_test = train_test_split(X, y, random_state=42)"}]},{"title":"Build the Pipeline","body":["We will now build a pipeline that consists of two steps: feature selection and SVM classification. We will use Scikit-learn's SelectKBest function for feature selection, and Scikit-learn's LinearSVC function for SVM classification. The SelectKBest function selects the k most informative features based on the f_classif method, which computes the ANOVA F-value between each feature and the target variable. We will set k=3 in this example."],"code":[{"lang":"python","text":"from sklearn.feature_selection import SelectKBest, f_classif\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.svm import LinearSVC\n\nanova_filter = SelectKBest(f_classif, k=3)\nclf = LinearSVC(dual=\"auto\")\nanova_svm = make_pipeline(anova_filter, clf)"}]},{"title":"Train the Pipeline","body":["We will now train the pipeline on the training subset using the fit method. During training, the SelectKBest function will select the 3 most informative features based on the ANOVA F-value, and the LinearSVC function will train a linear SVM classifier on the selected features."],"code":[{"lang":"python","text":"anova_svm.fit(X_train, y_train)"}]},{"title":"Evaluate the Pipeline","body":["We will now evaluate the pipeline on the testing subset using the predict method. The pipeline will select the 3 most informative features based on the ANOVA F-value, and the LinearSVC function will make predictions on the selected features."],"code":[{"lang":"python","text":"from sklearn.metrics import classification_report\n\ny_pred = anova_svm.predict(X_test)\nprint(classification_report(y_test, y_pred))"}]},{"title":"Inspect the Pipeline","body":["We can inspect the pipeline to better understand the model. We can use the index of the selected features to retrieve the original feature names."],"code":[{"lang":"python","text":"anova_svm[:-1].inverse_transform(anova_svm[-1].coef_)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"anova_svm[:-1].inverse_transform(anova_svm[-1].coef_)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-feature-transformations-with-ensembles-of-tr":{"intro":"In this lab, we will learn how to transform features into a higher dimensional, sparse space using an ensemble of trees. We will then train a linear model on these features. We will use different types of ensemble methods including Random Forest and Gradient Boosting and compare their performance.","steps":[{"title":"Data Preparation","body":["First, we will create a large dataset of 80,000 samples and split it into three sets:","• A set to train the ensemble methods which are later used to as a feature engineering transformer • A set to train the linear model • A set to test the linear model."],"code":[{"lang":"python","text":"from sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\n\nX, y = make_classification(n_samples=80_000, random_state=10)\n\nX_full_train, X_test, y_full_train, y_test = train_test_split(\n    X, y, test_size=0.5, random_state=10\n)\n\nX_train_ensemble, X_train_linear, y_train_ensemble, y_train_linear = train_test_split(\n    X_full_train, y_full_train, test_size=0.5, random_state=10\n)"}]},{"title":"Training Ensemble Methods","body":["For each of the ensemble methods, we will use 10 estimators and a maximum depth of 3 levels."],"code":[{"lang":"python","text":"from sklearn.ensemble import RandomForestClassifier, GradientBoostingClassifier\n\nn_estimators = 10\nmax_depth = 3\n\nrandom_forest = RandomForestClassifier(\n    n_estimators=n_estimators, max_depth=max_depth, random_state=10\n)\nrandom_forest.fit(X_train_ensemble, y_train_ensemble)\n\ngradient_boosting = GradientBoostingClassifier(\n    n_estimators=n_estimators, max_depth=max_depth, random_state=10\n)\n_ = gradient_boosting.fit(X_train_ensemble, y_train_ensemble)"}]},{"title":"Training Embedding Transformer","body":["Training Embedding Transformer","The RandomTreesEmbedding is an unsupervised method and does not require to be trained independently."],"code":[{"lang":"python","text":"from sklearn.ensemble import RandomTreesEmbedding\n\nrandom_tree_embedding = RandomTreesEmbedding(\n    n_estimators=n_estimators, max_depth=max_depth, random_state=0\n)\n\nrt_model = make_pipeline(random_tree_embedding, LogisticRegression(max_iter=1000))\nrt_model.fit(X_train_linear, y_train_linear)"}]},{"title":"Transforming Features with Random Forest and Gradient Boosting","body":["Transforming Features with Random Forest and Gradient Boosting","Now, we will create two pipelines that will use the above embedding as a preprocessing stage. The feature transformation will happen by calling the method apply. We will then pipeline random forest or gradient boosting with a logistic regression. However, the pipeline in scikit-learn expects a call to transform. Therefore, we wrapped the call to apply within a FunctionTransformer."],"code":[{"lang":"python","text":"from sklearn.preprocessing import FunctionTransformer\nfrom sklearn.preprocessing import OneHotEncoder\n\ndef rf_apply(X, model):\n    return model.apply(X)\n\nrf_leaves_yielder = FunctionTransformer(rf_apply, kw_args={\"model\": random_forest})\n\nrf_model = make_pipeline(\n    rf_leaves_yielder,\n    OneHotEncoder(handle_unknown=\"ignore\"),\n    LogisticRegression(max_iter=1000),\n)\nrf_model.fit(X_train_linear, y_train_linear)\n\ndef gbdt_apply(X, model):\n    return model.apply(X)[:, :, 0]\n\ngbdt_leaves_yielder = FunctionTransformer(\n    gbdt_apply, kw_args={\"model\": gradient_boosting}\n)\n\ngbdt_model = make_pipeline(\n    gbdt_leaves_yielder,\n    OneHotEncoder(handle_unknown=\"ignore\"),\n    LogisticRegression(max_iter=1000),\n)\ngbdt_model.fit(X_train_linear, y_train_linear)"}]},{"title":"Evaluating Models","body":["We can finally show the different ROC curves for all the models."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom sklearn.metrics import RocCurveDisplay\n\nfig, ax = plt.subplots()\n\nmodels = [\n    (\"RT embedding -> LR\", rt_model),\n    (\"RF\", random_forest),\n    (\"RF embedding -> LR\", rf_model),\n    (\"GBDT\", gradient_boosting),\n    (\"GBDT embedding -> LR\", gbdt_model),\n]\n\nmodel_displays = {}\nfor name, pipeline in models:\n    model_displays[name] = RocCurveDisplay.from_estimator(\n        pipeline, X_test, y_test, ax=ax, name=name\n    )\n_ = ax.set_title(\"ROC curve\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nfrom sklearn.metrics import RocCurveDisplay\n\nfig, ax = plt.subplots()\n\nmodels = [\n    (\"RT embedding -> LR\", rt_model),\n    (\"RF\", random_forest),\n    (\"RF embedding -> LR\", rf_model),\n    (\"GBDT\", gradient_boosting),\n    (\"GBDT embedding -> LR\", gbdt_model),\n]\n\nmodel_displays = {}\nfor name, pipeline in models:\n    model_displays[name] = RocCurveDisplay.from_estimator(\n        pipeline, X_test, y_test, ax=ax, name=name\n    )\n_ = ax.set_title(\"ROC curve\")"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-concatenating-multiple-feature-extraction-me":{"intro":"In this lab, we will learn how to concatenate multiple feature extraction methods using Python's scikit-learn library. We will use the FeatureUnion transformer to combine features obtained by PCA and univariate selection. Combining features using this transformer has the benefit that it allows cross-validation and grid searches over the whole process.","steps":[{"title":"Import Libraries","body":["We will begin by importing the required libraries. We will be using scikit-learn's Pipeline, FeatureUnion, GridSearchCV, SVC, load_iris, PCA, and SelectKBest classes."],"code":[{"lang":"python","text":"from sklearn.pipeline import Pipeline, FeatureUnion\nfrom sklearn.model_selection import GridSearchCV\nfrom sklearn.svm import SVC\nfrom sklearn.datasets import load_iris\nfrom sklearn.decomposition import PCA\nfrom sklearn.feature_selection import SelectKBest"}]},{"title":"Load the Dataset","body":["Next, we will load the iris dataset using the load_iris function."],"code":[{"lang":"python","text":"iris = load_iris()\n\nX, y = iris.data, iris.target"}]},{"title":"Feature Extraction","body":["Since the iris dataset is high-dimensional, we will perform feature extraction using PCA and univariate selection."],"code":[]},{"title":": PCA","body":["We will use PCA to reduce the dimensionality of the dataset."],"code":[{"lang":"python","text":"pca = PCA(n_components=2)"}]},{"title":": Univariate Selection","body":["We will use univariate selection to select the most significant features."],"code":[{"lang":"python","text":"selection = SelectKBest(k=1)"}]},{"title":": Combined Features","body":["We will combine the features obtained from PCA and univariate selection using the FeatureUnion transformer."],"code":[{"lang":"python","text":"combined_features = FeatureUnion([(\"pca\", pca), (\"univ_select\", selection)])"}]},{"title":": Transformed Dataset","body":["We will use the combined features to transform the dataset."],"code":[{"lang":"python","text":"X_features = combined_features.fit(X, y).transform(X)\nprint(\"Combined space has\", X_features.shape[1], \"features\")"}]},{"title":"Model Training","body":["We will train a support vector machine (SVM) model using the transformed dataset."],"code":[{"lang":"python","text":"svm = SVC(kernel=\"linear\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"pipeline = Pipeline([(\"features\", combined_features), (\"svm\", svm)])\n\nparam_grid = dict(\n    features__pca__n_components=[1, 2, 3],\n    features__univ_select__k=[1, 2],\n    svm__C=[0.1, 1, 10],\n)\n\ngrid_search = GridSearchCV(pipeline, param_grid=param_grid, verbose=10)\ngrid_search.fit(X, y)\nprint(grid_search.best_estimator_)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plot-forest-hist-grad-boosting-comparison":{"intro":"In this lab, we will compare the performance of two popular ensemble models, Random Forest (RF) and Histogram Gradient Boosting (HGBT), for a regression dataset in terms of score and computation time. We will vary the parameters that control the number of trees according to each estimator and plot the results to visualize the trade-off between elapsed computing time and mean test score.","steps":[{"title":"Load Dataset","body":["We will load the California housing dataset using the scikit-learn fetch_california_housing function. This dataset consists of 20,640 samples and 8 features."],"code":[{"lang":"python","text":"from sklearn.datasets import fetch_california_housing\n\nX, y = fetch_california_housing(return_X_y=True, as_frame=True)\nn_samples, n_features = X.shape\n\nprint(f\"The dataset consists of {n_samples} samples and {n_features} features\")"}]},{"title":"Define Models and Parameter Grids","body":["Define Models and Parameter Grids","We will define two models, Random Forest and Histogram Gradient Boosting, with their corresponding parameter grids using scikit-learn's RandomForestRegressor, HistGradientBoostingRegressor, and GridSearchCV classes. We will also set the number of physical cores on the host machine to use for parallel processing."],"code":[{"lang":"python","text":"import joblib\nimport pandas as pd\nfrom sklearn.ensemble import HistGradientBoostingRegressor, RandomForestRegressor\nfrom sklearn.model_selection import GridSearchCV, KFold\n\nN_CORES = joblib.cpu_count(only_physical_cores=True)\n\nmodels = {\n    \"Random Forest\": RandomForestRegressor(\n        min_samples_leaf=5, random_state=0, n_jobs=N_CORES\n    ),\n    \"Hist Gradient Boosting\": HistGradientBoostingRegressor(\n        max_leaf_nodes=15, random_state=0, early_stopping=False\n    ),\n}\n\nparam_grids = {\n    \"Random Forest\": {\"n_estimators\": [10, 20, 50, 100]},\n    \"Hist Gradient Boosting\": {\"max_iter\": [10, 20, 50, 100, 300, 500]},\n}\n\ncv = KFold(n_splits=4, shuffle=True, random_state=0)\n\nresults = []\n\nfor name, model in models.items():\n    grid_search = GridSearchCV(\n        estimator=model,\n        param_grid=param_grids[name],\n        return_train_score=True,\n        cv=cv,\n    ).fit(X, y)\n\n    result = {\"model\": name, \"cv_results\": pd.DataFrame(grid_search.cv_results_)}\n    results.append(result)"}]},{"title":"Compute Scores and Computation Times","body":["Compute Scores and Computation Times","We will compute the mean fit and score times for each combination of hyperparameters using the cv_results_ attribute of the GridSearchCV object. We will then plot the results using plotly.express.scatter and plotly.express.line to visualize the trade-off between elapsed computing time and mean test score."],"code":[{"lang":"python","text":"import plotly.express as px\nimport plotly.colors as colors\nfrom plotly.subplots import make_subplots\n\nfig = make_subplots(\n    rows=1,\n    cols=2,\n    shared_yaxes=True,\n    subplot_titles=[\"Train time vs score\", \"Predict time vs score\"],\n)\nmodel_names = [result[\"model\"] for result in results]\ncolors_list = colors.qualitative.Plotly * (\n    len(model_names) // len(colors.qualitative.Plotly) + 1\n)\n\nfor idx, result in enumerate(results):\n    cv_results = result[\"cv_results\"].round(3)\n    model_name = result[\"model\"]\n    param_name = list(param_grids[model_name].keys())[0]\n    cv_results[param_name] = cv_results[\"param_\" + param_name]\n    cv_results[\"model\"] = model_name\n\n    scatter_fig = px.scatter(\n        cv_results,\n        x=\"mean_fit_time\",\n        y=\"mean_test_score\",\n        error_x=\"std_fit_time\",\n        error_y=\"std_test_score\",\n        hover_data=param_name,\n        color=\"model\",\n    )\n    line_fig = px.line(\n        cv_results,\n        x=\"mean_fit_time\",\n        y=\"mean_test_score\",\n    )\n\n    scatter_trace = scatter_fig[\"data\"][0]\n    line_trace = line_fig[\"data\"][0]\n    scatter_trace.update(marker=dict(color=colors_list[idx]))\n    line_trace.update(line=dict(color=colors_list[idx]))\n    fig.add_trace(scatter_trace, row=1, col=1)\n    fig.add_trace(line_trace, row=1, col=1)\n\n    scatter_fig = px.scatter(\n        cv_results,\n        x=\"mean_score_time\",\n        y=\"mean_test_score\","}]},{"title":"Interpret Results","body":["We can observe that both HGBT and RF models improve when increasing the number of trees in the ensemble. However, the scores reach a plateau where adding new trees just makes fitting and scoring slower. The RF model reaches such plateau earlier and can never reach the test score of the largest HGBDT model. HGBT models uniformly dominate the RF models in the \"test score vs training speed trade-off\" and the \"test score vs prediction speed\" trade-off can also be more favorable to HGBT. HGBT almost always offers a more favorable speed-accuracy trade-off than RF, either with the default hyper-parameters or including the…"],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-feature-importance-with-random-forest":{"intro":"In this lab, we will use random forest to evaluate the importance of features on an artificial classification task. We will generate a synthetic dataset with only 3 informative features. The feature importances of the forest will be plotted, along with their inter-trees variability represented by the error bars.","steps":[{"title":"Import Libraries","body":["We will import the necessary libraries for this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.inspection import permutation_importance\nimport pandas as pd\nimport numpy as np\nimport time"}]},{"title":"Generate Data","body":["We will generate a synthetic dataset with only 3 informative features. We will explicitly not shuffle the dataset to ensure that the informative features will correspond to the three first columns of X. In addition, we will split our dataset into training and testing subsets."],"code":[{"lang":"python","text":"X, y = make_classification(\n    n_samples=1000,\n    n_features=10,\n    n_informative=3,\n    n_redundant=0,\n    n_repeated=0,\n    n_classes=2,\n    random_state=0,\n    shuffle=False,\n)\nX_train, X_test, y_train, y_test = train_test_split(X, y, stratify=y, random_state=42)"}]},{"title":"Fit Random Forest","body":["We will fit a random forest classifier to compute the feature importances."],"code":[{"lang":"python","text":"feature_names = [f\"feature {i}\" for i in range(X.shape[1])]\nforest = RandomForestClassifier(random_state=0)\nforest.fit(X_train, y_train)"}]},{"title":"Feature Importance based on Mean Decrease in Impurity","body":["Feature Importance based on Mean Decrease in Impurity","Feature importances are provided by the fitted attribute feature_importances_ and they are computed as the mean and standard deviation of accumulation of the impurity decrease within each tree. We will plot the impurity-based importance."],"code":[{"lang":"python","text":"start_time = time.time()\nimportances = forest.feature_importances_\nstd = np.std([tree.feature_importances_ for tree in forest.estimators_], axis=0)\nelapsed_time = time.time() - start_time\n\nprint(f\"Elapsed time to compute the importances: {elapsed_time:.3f} seconds\")\n\nforest_importances = pd.Series(importances, index=feature_names)\n\nfig, ax = plt.subplots()\nforest_importances.plot.bar(yerr=std, ax=ax)\nax.set_title(\"Feature importances using MDI\")\nax.set_ylabel(\"Mean decrease in impurity\")\nfig.tight_layout()"}]},{"title":"Feature Importance based on Feature Permutation","body":["Feature Importance based on Feature Permutation","Permutation feature importance overcomes limitations of the impurity-based feature importance: they do not have a bias toward high-cardinality features and can be computed on a left-out test set. We will compute the full permutation importance. Features are shuffled n times and the model refitted to estimate the importance of it. We will plot the importance ranking."],"code":[{"lang":"python","text":"start_time = time.time()\nresult = permutation_importance(\n    forest, X_test, y_test, n_repeats=10, random_state=42, n_jobs=2\n)\nelapsed_time = time.time() - start_time\nprint(f\"Elapsed time to compute the importances: {elapsed_time:.3f} seconds\")\n\nforest_importances = pd.Series(result.importances_mean, index=feature_names)\n\nfig, ax = plt.subplots()\nforest_importances.plot.bar(yerr=result.importances_std, ax=ax)\nax.set_title(\"Feature importances using permutation on full model\")\nax.set_ylabel(\"Mean accuracy decrease\")\nfig.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"start_time = time.time()\nresult = permutation_importance(\n    forest, X_test, y_test, n_repeats=10, random_state=42, n_jobs=2\n)\nelapsed_time = time.time() - start_time\nprint(f\"Elapsed time to compute the importances: {elapsed_time:.3f} seconds\")\n\nforest_importances = pd.Series(result.importances_mean, index=feature_names)\n\nfig, ax = plt.subplots()\nforest_importances.plot.bar(yerr=result.importances_std, ax=ax)\nax.set_title(\"Feature importances using permutation on full model\")\nax.set_ylabel(\"Mean accuracy decrease\")\nfig.tight_layout()\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-pixel-importances-with-parallel-forest-of-tr":{"intro":"In this lab, we will use the scikit-learn library to train a random forest on the Olivetti Faces dataset and evaluate the impurity-based feature importance. We will use the feature importances to create a heat map of the pixel importances. We will also parallelize the construction and computation of the predictions within multiple jobs.","steps":[{"title":"Load the data and model fitting","body":["Load the data and model fitting","We begin by loading the Olivetti Faces dataset and limiting the dataset to contain only the first five classes. Then we train a random forest on the dataset and evaluate the impurity-based feature importance. We will set the number of cores to use for the tasks."],"code":[{"lang":"python","text":"from sklearn.datasets import fetch_olivetti_faces\n\n# We select the number of cores to use to perform parallel fitting of\n# the forest model. `-1` means use all available cores.\nn_jobs = -1\n\n# Load the faces dataset\ndata = fetch_olivetti_faces()\nX, y = data.data, data.target\n\n# Limit the dataset to 5 classes.\nmask = y < 5\nX = X[mask]\ny = y[mask]\n\n# A random forest classifier will be fitted to compute the feature importances.\nfrom sklearn.ensemble import RandomForestClassifier\n\nforest = RandomForestClassifier(n_estimators=750, n_jobs=n_jobs, random_state=42)\n\nforest.fit(X, y)"}]},{"title":"Evaluate Feature Importance","body":["We evaluate the feature importance based on mean decrease in impurity (MDI). Feature importances are provided by the fitted attribute feature_importances_ and they are computed as the mean and standard deviation of accumulation of the impurity decrease within each tree."],"code":[{"lang":"python","text":"import time\nimport matplotlib.pyplot as plt\n\nstart_time = time.time()\nimg_shape = data.images[0].shape\nimportances = forest.feature_importances_\nelapsed_time = time.time() - start_time\n\nprint(f\"Elapsed time to compute the importances: {elapsed_time:.3f} seconds\")\nimp_reshaped = importances.reshape(img_shape)\nplt.matshow(imp_reshaped, cmap=plt.cm.hot)\nplt.title(\"Pixel importances using impurity values\")\nplt.colorbar()\nplt.show()"}]},{"title":"Interpret the Heatmap","body":["The heat map shows the pixel importances. The hotter the pixel, the more important it is. We can observe the important pixels that contribute to the classification of the Olivetti Faces dataset."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-plot-forest-iris":{"intro":"This lab demonstrates how to plot the decision surfaces of forests of randomized trees on the iris dataset using Python's scikit-learn library. The iris dataset is a commonly used dataset for classification tasks. In this lab, we will compare the decision surfaces learned by a decision tree classifier, a random forest classifier, an extra-trees classifier, and an AdaBoost classifier.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries required to plot the decision surfaces on the iris dataset."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import ListedColormap\n\nfrom sklearn.datasets import load_iris\nfrom sklearn.ensemble import (\n    RandomForestClassifier,\n    ExtraTreesClassifier,\n    AdaBoostClassifier,\n)\nfrom sklearn.tree import DecisionTreeClassifier"}]},{"title":"Define Parameters","body":["In this step, we will define the parameters required to plot the decision surfaces on the iris dataset."],"code":[{"lang":"python","text":"# Parameters\nn_classes = 3\nn_estimators = 30\ncmap = plt.cm.RdYlBu\nplot_step = 0.02  # fine step width for decision surface contours\nplot_step_coarser = 0.5  # step widths for coarse classifier guesses\nRANDOM_SEED = 13  # fix the seed on each iteration"}]},{"title":"Load Data","body":["In this step, we will load the iris dataset."],"code":[{"lang":"python","text":"# Load data\niris = load_iris()"}]},{"title":"Define Models","body":["In this step, we will define the models to be used for plotting the decision surfaces on the iris dataset."],"code":[{"lang":"python","text":"models = [\n    DecisionTreeClassifier(max_depth=None),\n    RandomForestClassifier(n_estimators=n_estimators),\n    ExtraTreesClassifier(n_estimators=n_estimators),\n    AdaBoostClassifier(DecisionTreeClassifier(max_depth=3), n_estimators=n_estimators),\n]"}]},{"title":"Plot Decision Surfaces","body":["In this step, we will plot the decision surfaces of the defined models on the iris dataset."],"code":[{"lang":"python","text":"plot_idx = 1\n\nfor pair in ([0, 1], [0, 2], [2, 3]):\n    for model in models:\n        # We only take the two corresponding features\n        X = iris.data[:, pair]\n        y = iris.target\n\n        # Shuffle\n        idx = np.arange(X.shape[0])\n        np.random.seed(RANDOM_SEED)\n        np.random.shuffle(idx)\n        X = X[idx]\n        y = y[idx]\n\n        # Standardize\n        mean = X.mean(axis=0)\n        std = X.std(axis=0)\n        X = (X - mean) / std\n\n        # Train\n        model.fit(X, y)\n\n        scores = model.score(X, y)\n        # Create a title for each column and the console by using str() and\n        # slicing away useless parts of the string\n        model_title = str(type(model)).split(\".\")[-1][:-2][: -len(\"Classifier\")]\n\n        model_details = model_title\n        if hasattr(model, \"estimators_\"):\n            model_details += \" with {} estimators\".format(len(model.estimators_))\n        print(model_details + \" with features\", pair, \"has a score of\", scores)\n\n        plt.subplot(3, 4, plot_idx)\n        if plot_idx <= len(models):\n            # Add a title at the top of each column\n            plt.title(model_title, fontsize=9)\n\n        # Now plot the decision boundary using a fine mesh as input to a\n        # filled contour plot\n        x_min, x_max = X[:, 0].min() - 1, X[:, 0].max() + 1\n        y_min, y_max = X[:, 1].min() - 1, X[:, 1].max() + 1\n        xx, yy = np.meshgrid(\n            np.arange(x_min, x_max, plot_step), np.arange(y_min, y_max, plot_step)\n        )\n\n        # Plot either a single DecisionTreeClassifier or alpha blend the\n        # decision surfaces of the ensemble of classifiers"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plot_idx = 1\n\nfor pair in ([0, 1], [0, 2], [2, 3]):\n    for model in models:\n        # We only take the two corresponding features\n        X = iris.data[:, pair]\n        y = iris.target\n\n        # Shuffle\n        idx = np.arange(X.shape[0])\n        np.random.seed(RANDOM_SEED)\n        np.random.shuffle(idx)\n        X = X[idx]\n        y = y[idx]\n\n        # Standardize\n        mean = X.mean(axis=0)\n        std = X.std(axis=0)\n        X = (X - mean) / std\n\n        # Train\n        model.fit(X, y)\n\n        scores = model.score(X, y)\n        # Create a title for each column and the console by using str() and\n        # slicing away useless parts of the string\n        model_title = str(type(model)).split(\".\")[-1][:-2][: -len(\"Classifier\")]\n\n        model_details = model_title\n        if hasattr(model, \"estimators_\"):\n            model_details += \" with {} estimators\".format(len(model.estimators_))\n        print(model_details + \" with features\", pair, \"has a score of\", scores)\n\n        plt.subplot(3, 4, plot_idx)\n        if plot_idx <= len(models):\n            # Add a title at the top of each column\n            plt.title(model_title, fontsize=9)\n\n        # Now plot the decision boundary using a fine mesh as input to a\n        # filled contour plot\n        x_min, x_max = X[:, 0].min() - 1, X[:, 0].max() + 1\n        y_min, y_max = X[:, 1].min() - 1, X[:, 1].max() + 1\n        xx, yy = np.meshgrid(\n            np.arange(x_min, x_max, plot_step), np.arange(y_min, y_max, plot_step)\n        )\n\n        # Plot either a single DecisionTreeClassifier or alpha blend the\n        # decision surfaces of the ensemble of classifiers"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-gaussian-mixture-model":{"intro":"This lab will guide you through the implementation of Gaussian Mixture Models (GMMs) using the scikit-learn library in Python. GMMs are probabilistic models that assume that the data is generated from a mixture of several Gaussian distributions. They are widely used in various fields such as computer vision, finance, and bioinformatics for clustering and density estimation tasks.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries for this lab. We will use NumPy for numerical computing, Matplotlib for data visualization, and scikit-learn for GMM implementation."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn import mixture"}]},{"title":"Generate Data","body":["In this step, we will generate a sample dataset that consists of two Gaussian distributions with different means and covariances."],"code":[{"lang":"python","text":"n_samples = 500\n\nnp.random.seed(0)\nC = np.array([[0.0, -0.1], [1.7, 0.4]])\nX = np.r_[\n    np.dot(np.random.randn(n_samples, 2), C),\n    0.7 * np.random.randn(n_samples, 2) + np.array([-6, 3]),\n]"}]},{"title":"Implement Gaussian Mixture Model","body":["Implement Gaussian Mixture Model","In this step, we will implement the Gaussian Mixture Model using the GaussianMixture class of scikit-learn. We will fit the model to our dataset and predict the cluster labels for each data point. Finally, we will plot the results."],"code":[{"lang":"python","text":"# Create a GMM object with 5 components\ngmm = mixture.GaussianMixture(n_components=5, covariance_type=\"full\")\n\n# Fit the GMM to the data\ngmm.fit(X)\n\n# Predict the cluster labels\nY_ = gmm.predict(X)\n\n# Plot the results\ncolor_iter = [\"navy\", \"c\", \"cornflowerblue\", \"gold\", \"darkorange\"]\n\nfor i, color in enumerate(color_iter):\n    plt.scatter(\n        X[Y_ == i, 0], X[Y_ == i, 1], 0.8, color=color, label=\"Cluster {}\".format(i)\n    )\n\nplt.legend(loc=\"best\")\nplt.title(\"Gaussian Mixture Model\")\nplt.show()"}]},{"title":"Implement Bayesian Gaussian Mixture Model","body":["Implement Bayesian Gaussian Mixture Model","In this step, we will implement the Bayesian Gaussian Mixture Model using the BayesianGaussianMixture class of scikit-learn. This model has a Dirichlet process prior that automatically adapts the number of clusters based on the data. We will fit the model to our dataset and predict the cluster labels for each data point. Finally, we will plot the results."],"code":[{"lang":"python","text":"# Create a Bayesian GMM object with 5 components\ndpgmm = mixture.BayesianGaussianMixture(n_components=5, covariance_type=\"full\")\n\n# Fit the Bayesian GMM to the data\ndpgmm.fit(X)\n\n# Predict the cluster labels\nY_ = dpgmm.predict(X)\n\n# Plot the results\ncolor_iter = [\"navy\", \"c\", \"cornflowerblue\", \"gold\", \"darkorange\"]\n\nfor i, color in enumerate(color_iter):\n    plt.scatter(\n        X[Y_ == i, 0], X[Y_ == i, 1], 0.8, color=color, label=\"Cluster {}\".format(i)\n    )\n\nplt.legend(loc=\"best\")\nplt.title(\"Bayesian Gaussian Mixture Model with a Dirichlet process prior\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create a Bayesian GMM object with 5 components\ndpgmm = mixture.BayesianGaussianMixture(n_components=5, covariance_type=\"full\")\n\n# Fit the Bayesian GMM to the data\ndpgmm.fit(X)\n\n# Predict the cluster labels\nY_ = dpgmm.predict(X)\n\n# Plot the results\ncolor_iter = [\"navy\", \"c\", \"cornflowerblue\", \"gold\", \"darkorange\"]\n\nfor i, color in enumerate(color_iter):\n    plt.scatter(\n        X[Y_ == i, 0], X[Y_ == i, 1], 0.8, color=color, label=\"Cluster {}\".format(i)\n    )\n\nplt.legend(loc=\"best\")\nplt.title(\"Bayesian Gaussian Mixture Model with a Dirichlet process prior\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-gaussian-mixture-model-covariances":{"intro":"This tutorial demonstrates the use of different covariance types for Gaussian mixture models (GMMs). GMMs are often used for clustering, and we can compare the obtained clusters with the actual classes from the dataset. We initialize the means of the Gaussians with the means of the classes from the training set to make this comparison valid. We plot predicted labels on both training and held-out test data using a variety of GMM covariance types on the iris dataset. We compare GMMs with spherical, diagonal, full, and tied covariance matrices in increasing order of performance.","steps":[{"title":"Import Libraries","body":[],"code":[{"lang":"python","text":"import matplotlib as mpl\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom sklearn import datasets\nfrom sklearn.mixture import GaussianMixture\nfrom sklearn.model_selection import StratifiedKFold"}]},{"title":"Load the Iris dataset","body":[],"code":[{"lang":"python","text":"iris = datasets.load_iris()"}]},{"title":"Prepare training and test data","body":["Prepare training and test data"],"code":[{"lang":"python","text":"skf = StratifiedKFold(n_splits=4)\ntrain_index, test_index = next(iter(skf.split(iris.data, iris.target)))\n\nX_train = iris.data[train_index]\ny_train = iris.target[train_index]\nX_test = iris.data[test_index]\ny_test = iris.target[test_index]"}]},{"title":"Set up GMM estimators for different covariance types","body":["Set up GMM estimators for different covariance types"],"code":[{"lang":"python","text":"colors = [\"navy\", \"turquoise\", \"darkorange\"]\nn_classes = len(np.unique(y_train))\n\nestimators = {\n    cov_type: GaussianMixture(\n        n_components=n_classes, covariance_type=cov_type, max_iter=20, random_state=0\n    )\n    for cov_type in [\"spherical\", \"diag\", \"tied\", \"full\"]\n}\n\nn_estimators = len(estimators)"}]},{"title":"Define a function to plot ellipses for GMMs","body":["Define a function to plot ellipses for GMMs"],"code":[{"lang":"python","text":"def make_ellipses(gmm, ax):\n    for n, color in enumerate(colors):\n        if gmm.covariance_type == \"full\":\n            covariances = gmm.covariances_[n][:2, :2]\n        elif gmm.covariance_type == \"tied\":\n            covariances = gmm.covariances_[:2, :2]\n        elif gmm.covariance_type == \"diag\":\n            covariances = np.diag(gmm.covariances_[n][:2])\n        elif gmm.covariance_type == \"spherical\":\n            covariances = np.eye(gmm.means_.shape[1]) * gmm.covariances_[n]\n        v, w = np.linalg.eigh(covariances)\n        u = w[0] / np.linalg.norm(w[0])\n        angle = np.arctan2(u[1], u[0])\n        angle = 180 * angle / np.pi\n        v = 2.0 * np.sqrt(2.0) * np.sqrt(v)\n        ell = mpl.patches.Ellipse(\n            gmm.means_[n, :2], v[0], v[1], angle=180 + angle, color=color\n        )\n        ell.set_clip_box(ax.bbox)\n        ell.set_alpha(0.5)\n        ax.add_artist(ell)\n        ax.set_aspect(\"equal\", \"datalim\")"}]},{"title":"Plot GMMs for different covariance types","body":["Plot GMMs for different covariance types"],"code":[{"lang":"python","text":"plt.figure(figsize=(3 * n_estimators // 2, 6))\nplt.subplots_adjust(\n    bottom=0.01, top=0.95, hspace=0.15, wspace=0.05, left=0.01, right=0.99\n)\n\nfor index, (name, estimator) in enumerate(estimators.items()):\n    estimator.means_init = np.array(\n        [X_train[y_train == i].mean(axis=0) for i in range(n_classes)]\n    )\n\n    estimator.fit(X_train)\n\n    h = plt.subplot(2, n_estimators // 2, index + 1)\n    make_ellipses(estimator, h)\n\n    for n, color in enumerate(colors):\n        data = iris.data[iris.target == n]\n        plt.scatter(\n            data[:, 0], data[:, 1], s=0.8, color=color, label=iris.target_names[n]\n        )\n\n    for n, color in enumerate(colors):\n        data = X_test[y_test == n]\n        plt.scatter(data[:, 0], data[:, 1], marker=\"x\", color=color)\n\n    y_train_pred = estimator.predict(X_train)\n    train_accuracy = np.mean(y_train_pred.ravel() == y_train.ravel()) * 100\n    plt.text(0.05, 0.9, \"Train accuracy: %.1f\" % train_accuracy, transform=h.transAxes)\n\n    y_test_pred = estimator.predict(X_test)\n    test_accuracy = np.mean(y_test_pred.ravel() == y_test.ravel()) * 100\n    plt.text(0.05, 0.8, \"Test accuracy: %.1f\" % test_accuracy, transform=h.transAxes)\n\n    plt.xticks(())\n    plt.yticks(())\n    plt.title(name)\n\nplt.legend(scatterpoints=1, loc=\"lower right\", prop=dict(size=12))\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.figure(figsize=(3 * n_estimators // 2, 6))\nplt.subplots_adjust(\n    bottom=0.01, top=0.95, hspace=0.15, wspace=0.05, left=0.01, right=0.99\n)\n\nfor index, (name, estimator) in enumerate(estimators.items()):\n    estimator.means_init = np.array(\n        [X_train[y_train == i].mean(axis=0) for i in range(n_classes)]\n    )\n\n    estimator.fit(X_train)\n\n    h = plt.subplot(2, n_estimators // 2, index + 1)\n    make_ellipses(estimator, h)\n\n    for n, color in enumerate(colors):\n        data = iris.data[iris.target == n]\n        plt.scatter(\n            data[:, 0], data[:, 1], s=0.8, color=color, label=iris.target_names[n]\n        )\n\n    for n, color in enumerate(colors):\n        data = X_test[y_test == n]\n        plt.scatter(data[:, 0], data[:, 1], marker=\"x\", color=color)\n\n    y_train_pred = estimator.predict(X_train)\n    train_accuracy = np.mean(y_train_pred.ravel() == y_train.ravel()) * 100\n    plt.text(0.05, 0.9, \"Train accuracy: %.1f\" % train_accuracy, transform=h.transAxes)\n\n    y_test_pred = estimator.predict(X_test)\n    test_accuracy = np.mean(y_test_pred.ravel() == y_test.ravel()) * 100\n    plt.text(0.05, 0.8, \"Test accuracy: %.1f\" % test_accuracy, transform=h.transAxes)\n\n    plt.xticks(())\n    plt.yticks(())\n    plt.title(name)\n\nplt.legend(scatterpoints=1, loc=\"lower right\", prop=dict(size=12))\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-gaussian-mixture-model-initialization-method":{"intro":"In this lab, we will learn about different initialization methods for Gaussian Mixture Models (GMM). We will use scikit-learn library to generate sample data and visualize the clustering results. There are four different methods for the initialization parameter _init_param_: kmeans (default), random, random_from_data, and k-means++.","steps":[{"title":"Import libraries and generate sample data","body":["Import libraries and generate sample data","We will start by importing the necessary libraries and generating some sample data using the make_blobs function from scikit-learn."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom sklearn.mixture import GaussianMixture\nfrom sklearn.utils.extmath import row_norms\nfrom sklearn.datasets._samples_generator import make_blobs\nfrom timeit import default_timer as timer\n\n# Generate some data\nX, y_true = make_blobs(n_samples=4000, centers=4, cluster_std=0.60, random_state=0)\nX = X[:, ::-1]\n\nn_samples = 4000\nn_components = 4\nx_squared_norms = row_norms(X, squared=True)"}]},{"title":"Define a function to get initial means","body":["Define a function to get initial means","Next, we will define a function get_initial_means that takes the sample data, initialization method, and random state as inputs and returns the initialization means."],"code":[{"lang":"python","text":"def get_initial_means(X, init_params, r):\n    # Run a GaussianMixture with max_iter=0 to output the initialization means\n    gmm = GaussianMixture(\n        n_components=4, init_params=init_params, tol=1e-9, max_iter=0, random_state=r\n    ).fit(X)\n    return gmm.means_"}]},{"title":"Plot the sample data and initialization centers","body":["Plot the sample data and initialization centers","We will now plot the sample data and the initialization centers for each initialization method using different colors. We will also calculate the time taken for initialization and the number of iterations taken for the GMM to converge."],"code":[{"lang":"python","text":"methods = [\"kmeans\", \"random_from_data\", \"k-means++\", \"random\"]\ncolors = [\"navy\", \"turquoise\", \"cornflowerblue\", \"darkorange\"]\ntimes_init = {}\nrelative_times = {}\n\nplt.figure(figsize=(4 * len(methods) // 2, 6))\nplt.subplots_adjust(\n    bottom=0.1, top=0.9, hspace=0.15, wspace=0.05, left=0.05, right=0.95\n)\n\nfor n, method in enumerate(methods):\n    r = np.random.RandomState(seed=1234)\n    plt.subplot(2, len(methods) // 2, n + 1)\n\n    start = timer()\n    ini = get_initial_means(X, method, r)\n    end = timer()\n    init_time = end - start\n\n    gmm = GaussianMixture(\n        n_components=4, means_init=ini, tol=1e-9, max_iter=2000, random_state=r\n    ).fit(X)\n\n    times_init[method] = init_time\n    for i, color in enumerate(colors):\n        data = X[gmm.predict(X) == i]\n        plt.scatter(data[:, 0], data[:, 1], color=color, marker=\"x\")\n\n    plt.scatter(\n        ini[:, 0], ini[:, 1], s=75, marker=\"D\", c=\"orange\", lw=1.5, edgecolors=\"black\"\n    )\n    relative_times[method] = times_init[method] / times_init[methods[0]]\n\n    plt.xticks(())\n    plt.yticks(())\n    plt.title(method, loc=\"left\", fontsize=12)\n    plt.title(\n        \"Iter %i | Init Time %.2fx\" % (gmm.n_iter_, relative_times[method]),\n        loc=\"right\",\n        fontsize=10,\n    )\nplt.suptitle(\"GMM iterations and relative time taken to initialize\")\nplt.show()"}]},{"title":"Interpret the results","body":["We can see from the plot that k-means++ does a good job of both low time to initialize and low number of GaussianMixture iterations to converge. When initialized with random_from_data or random, the model takes more iterations to converge. All three alternative methods take less time to initialize when compared to kmeans."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-density-estimation-with-gaussian-mixture-mod":{"intro":"In this lab, we will use the scikit-learn library to generate a Gaussian mixture dataset. We will then fit a Gaussian Mixture Model (GMM) to the dataset and plot the density estimation of the mixture of Gaussians. GMMs can be used to model and estimate the probability distribution of a dataset.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries: NumPy for numerical computations and Matplotlib for visualizations. We will also import the GaussianMixture class from the scikit-learn library to fit the GMM to our dataset."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom sklearn import mixture"}]},{"title":"Generate Data","body":["Next, we will generate a Gaussian mixture dataset with two components. We will create a shifted Gaussian dataset centered on (20, 20) and a zero-centered stretched Gaussian dataset. We will then concatenate the two datasets into the final training set."],"code":[{"lang":"python","text":"n_samples = 300\n\n# generate random sample, two components\nnp.random.seed(0)\n\n# generate spherical data centered on (20, 20)\nshifted_gaussian = np.random.randn(n_samples, 2) + np.array([20, 20])\n\n# generate zero centered stretched Gaussian data\nC = np.array([[0.0, -0.7], [3.5, 0.7]])\nstretched_gaussian = np.dot(np.random.randn(n_samples, 2), C)\n\n# concatenate the two datasets into the final training set\nX_train = np.vstack([shifted_gaussian, stretched_gaussian])"}]},{"title":"Fit Gaussian Mixture Model","body":["We will now fit a GMM to the dataset using the GaussianMixture class from scikit-learn. We will set the number of components to 2 and the covariance type to \"full\"."],"code":[{"lang":"python","text":"# fit a Gaussian Mixture Model with two components\nclf = mixture.GaussianMixture(n_components=2, covariance_type=\"full\")\nclf.fit(X_train)"}]},{"title":"Plot Density Estimation","body":["We will now plot the density estimation of the mixture of Gaussians. We will create a meshgrid of points over the range of the dataset and calculate the negative log-likelihood predicted by the GMM for each point. We will then display the predicted scores as a contour plot and scatter plot the training data."],"code":[{"lang":"python","text":"# display predicted scores by the model as a contour plot\nx = np.linspace(-20.0, 30.0)\ny = np.linspace(-20.0, 40.0)\nX, Y = np.meshgrid(x, y)\nXX = np.array([X.ravel(), Y.ravel()]).T\nZ = -clf.score_samples(XX)\nZ = Z.reshape(X.shape)\n\nCS = plt.contour(\n    X, Y, Z, norm=LogNorm(vmin=1.0, vmax=1000.0), levels=np.logspace(0, 3, 10)\n)\nCB = plt.colorbar(CS, shrink=0.8, extend=\"both\")\nplt.scatter(X_train[:, 0], X_train[:, 1], 0.8)\n\nplt.title(\"Density Estimation with Gaussian Mixture Models\")\nplt.axis(\"tight\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# display predicted scores by the model as a contour plot\nx = np.linspace(-20.0, 30.0)\ny = np.linspace(-20.0, 40.0)\nX, Y = np.meshgrid(x, y)\nXX = np.array([X.ravel(), Y.ravel()]).T\nZ = -clf.score_samples(XX)\nZ = Z.reshape(X.shape)\n\nCS = plt.contour(\n    X, Y, Z, norm=LogNorm(vmin=1.0, vmax=1000.0), levels=np.logspace(0, 3, 10)\n)\nCB = plt.colorbar(CS, shrink=0.8, extend=\"both\")\nplt.scatter(X_train[:, 0], X_train[:, 1], 0.8)\n\nplt.title(\"Density Estimation with Gaussian Mixture Models\")\nplt.axis(\"tight\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-gaussian-mixture-model-selection":{"intro":"In this lab, we will learn how to perform model selection with Gaussian Mixture Models (GMM) using information-theory criteria. Model selection concerns both the covariance type and the number of components in the model. We will use the Akaike Information Criterion (AIC) and the Bayes Information Criterion (BIC) to select the best model. We will generate two components by randomly sampling the standard normal distribution. One component is kept spherical yet shifted and re-scaled. The other one is deformed to have a more general covariance matrix.","steps":[{"title":"Data Generation","body":["We generate two components (each one containing n_samples) by randomly sampling the standard normal distribution as returned by numpy.random.randn. One component is kept spherical yet shifted and re-scaled. The other one is deformed to have a more general covariance matrix."],"code":[{"lang":"python","text":"import numpy as np\n\nn_samples = 500\nnp.random.seed(0)\nC = np.array([[0.0, -0.1], [1.7, 0.4]])\ncomponent_1 = np.dot(np.random.randn(n_samples, 2), C)  # general\ncomponent_2 = 0.7 * np.random.randn(n_samples, 2) + np.array([-4, 1])  # spherical\n\nX = np.concatenate([component_1, component_2])"}]},{"title":"Visualization","body":["We can visualize the different components using Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.scatter(component_1[:, 0], component_1[:, 1], s=0.8)\nplt.scatter(component_2[:, 0], component_2[:, 1], s=0.8)\nplt.title(\"Gaussian Mixture components\")\nplt.axis(\"equal\")\nplt.show()"}]},{"title":"Model Training and Selection","body":["We vary the number of components from 1 to 6 and the type of covariance parameters to use:","• \"full\": each component has its own general covariance matrix. • \"tied\": all components share the same general covariance matrix. • \"diag\": each component has its own diagonal covariance matrix. • \"spherical\": each component has its own single variance.","We score the different models and keep the best model (the lowest BIC). This is done by using GridSearchCV and a user-defined score function which returns the negative BIC score. The best set of parameters and estimator are stored in best_parameters_ and best_estimator_, respectively."],"code":[{"lang":"python","text":"from sklearn.mixture import GaussianMixture\nfrom sklearn.model_selection import GridSearchCV\n\ndef gmm_bic_score(estimator, X):\n    \"\"\"Callable to pass to GridSearchCV that will use the BIC score.\"\"\"\n    # Make it negative since GridSearchCV expects a score to maximize\n    return -estimator.bic(X)\n\nparam_grid = {\n    \"n_components\": range(1, 7),\n    \"covariance_type\": [\"spherical\", \"tied\", \"diag\", \"full\"],\n}\ngrid_search = GridSearchCV(\n    GaussianMixture(), param_grid=param_grid, scoring=gmm_bic_score\n)\ngrid_search.fit(X)"}]},{"title":"Plot the BIC Scores","body":["We create a pandas.DataFrame from the results of the cross-validation done by the grid search. We re-inverse the sign of the BIC score to show the effect of minimizing it. We use seaborn to plot the BIC scores."],"code":[{"lang":"python","text":"import pandas as pd\nimport seaborn as sns\n\ndf = pd.DataFrame(grid_search.cv_results_)[\n    [\"param_n_components\", \"param_covariance_type\", \"mean_test_score\"]\n]\ndf[\"mean_test_score\"] = -df[\"mean_test_score\"]\ndf = df.rename(\n    columns={\n        \"param_n_components\": \"Number of components\",\n        \"param_covariance_type\": \"Type of covariance\",\n        \"mean_test_score\": \"BIC score\",\n    }\n)\ndf.sort_values(by=\"BIC score\").head()\n\nsns.catplot(\n    data=df,\n    kind=\"bar\",\n    x=\"Number of components\",\n    y=\"BIC score\",\n    hue=\"Type of covariance\",\n)\nplt.show()"}]},{"title":"Plot the Best Model","body":["We plot an ellipse to show each Gaussian component of the selected model. For such purpose, one needs to find the eigenvalues of the covariance matrices as returned by the covariances_ attribute. The shape of such matrices depends on the covariance_type:","• \"full\": (n_components, n_features, n_features) • \"tied\": (n_features, n_features) • \"diag\": (n_components, n_features) • \"spherical\": (n_components,)"],"code":[{"lang":"python","text":"from matplotlib.patches import Ellipse\nfrom scipy import linalg\n\ncolor_iter = sns.color_palette(\"tab10\", 2)[::-1]\nY_ = grid_search.predict(X)\n\nfig, ax = plt.subplots()\n\nfor i, (mean, cov, color) in enumerate(\n    zip(\n        grid_search.best_estimator_.means_,\n        grid_search.best_estimator_.covariances_,\n        color_iter,\n    )\n):\n    v, w = linalg.eigh(cov)\n    if not np.any(Y_ == i):\n        continue\n    plt.scatter(X[Y_ == i, 0], X[Y_ == i, 1], 0.8, color=color)\n\n    angle = np.arctan2(w[0][1], w[0][0])\n    angle = 180.0 * angle / np.pi  # convert to degrees\n    v = 2.0 * np.sqrt(2.0) * np.sqrt(v)\n    ellipse = Ellipse(mean, v[0], v[1], angle=180.0 + angle, color=color)\n    ellipse.set_clip_box(fig.bbox)\n    ellipse.set_alpha(0.5)\n    ax.add_artist(ellipse)\n\nplt.title(\n    f\"Selected GMM: {grid_search.best_params_['covariance_type']} model, \"\n    f\"{grid_search.best_params_['n_components']} components\"\n)\nplt.axis(\"equal\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from matplotlib.patches import Ellipse\nfrom scipy import linalg\n\ncolor_iter = sns.color_palette(\"tab10\", 2)[::-1]\nY_ = grid_search.predict(X)\n\nfig, ax = plt.subplots()\n\nfor i, (mean, cov, color) in enumerate(\n    zip(\n        grid_search.best_estimator_.means_,\n        grid_search.best_estimator_.covariances_,\n        color_iter,\n    )\n):\n    v, w = linalg.eigh(cov)\n    if not np.any(Y_ == i):\n        continue\n    plt.scatter(X[Y_ == i, 0], X[Y_ == i, 1], 0.8, color=color)\n\n    angle = np.arctan2(w[0][1], w[0][0])\n    angle = 180.0 * angle / np.pi  # convert to degrees\n    v = 2.0 * np.sqrt(2.0) * np.sqrt(v)\n    ellipse = Ellipse(mean, v[0], v[1], angle=180.0 + angle, color=color)\n    ellipse.set_clip_box(fig.bbox)\n    ellipse.set_alpha(0.5)\n    ax.add_artist(ellipse)\n\nplt.title(\n    f\"Selected GMM: {grid_search.best_params_['covariance_type']} model, \"\n    f\"{grid_search.best_params_['n_components']} components\"\n)\nplt.axis(\"equal\")\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-gaussian-mixture-model-sine-curve":{"intro":"In this lab, we will use the Gaussian Mixture Model algorithm to fit a dataset that follows a noisy sine curve. We will use two different types of Gaussian Mixture Models, namely the Expectation-Maximization algorithm and the Bayesian Gaussian Mixture Model with a Dirichlet process prior.","steps":[{"title":"Load Required Libraries","body":["We will start by loading the required libraries for this lab."],"code":[{"lang":"python","text":"import itertools\n\nimport numpy as np\nfrom scipy import linalg\nimport matplotlib.pyplot as plt\nimport matplotlib as mpl\n\nfrom sklearn import mixture"}]},{"title":"Generate Dataset","body":["Next, we will generate a dataset that follows a noisy sine curve."],"code":[{"lang":"python","text":"# Parameters\nn_samples = 100\n\n# Generate random sample following a sine curve\nnp.random.seed(0)\nX = np.zeros((n_samples, 2))\nstep = 4.0 * np.pi / n_samples\n\nfor i in range(X.shape[0]):\n    x = i * step - 6.0\n    X[i, 0] = x + np.random.normal(0, 0.1)\n    X[i, 1] = 3.0 * (np.sin(x) + np.random.normal(0, 0.2))"}]},{"title":"Fit a Gaussian Mixture Model with EM","body":["Fit a Gaussian Mixture Model with EM","We will fit a classical Gaussian Mixture Model with 10 components fit with the Expectation-Maximization algorithm."],"code":[{"lang":"python","text":"# Fit a Gaussian mixture with EM using ten components\ngmm = mixture.GaussianMixture(\n    n_components=10, covariance_type=\"full\", max_iter=100\n).fit(X)"}]},{"title":"Plot the Results of EM Algorithm","body":["Plot the Results of EM Algorithm","We will plot the results of the Expectation-Maximization algorithm."],"code":[{"lang":"python","text":"def plot_results(X, Y, means, covariances, index, title):\n    splot = plt.subplot(5, 1, 1 + index)\n    for i, (mean, covar, color) in enumerate(zip(means, covariances, color_iter)):\n        v, w = linalg.eigh(covar)\n        v = 2.0 * np.sqrt(2.0) * np.sqrt(v)\n        u = w[0] / linalg.norm(w[0])\n        # as the DP will not use every component it has access to\n        # unless it needs it, we shouldn't plot the redundant\n        # components.\n        if not np.any(Y == i):\n            continue\n        plt.scatter(X[Y == i, 0], X[Y == i, 1], 0.8, color=color)\n\n        # Plot an ellipse to show the Gaussian component\n        angle = np.arctan(u[1] / u[0])\n        angle = 180.0 * angle / np.pi  # convert to degrees\n        ell = mpl.patches.Ellipse(mean, v[0], v[1], angle=180.0 + angle, color=color)\n        ell.set_clip_box(splot.bbox)\n        ell.set_alpha(0.5)\n        splot.add_artist(ell)\n\n    plt.xlim(-6.0, 4.0 * np.pi - 6.0)\n    plt.ylim(-5.0, 5.0)\n    plt.title(title)\n    plt.xticks(())\n    plt.yticks(())\n\nplot_results(\n    X, gmm.predict(X), gmm.means_, gmm.covariances_, 0, \"Expectation-maximization\"\n)"}]},{"title":"Fit a Bayesian Gaussian Mixture Model with a Dirichlet process prior","body":["Fit a Bayesian Gaussian Mixture Model with a Dirichlet process prior","We will now fit a Bayesian Gaussian Mixture Model with a Dirichlet process prior. We will set a low value of the concentration prior to make the model favor a lower number of active components."],"code":[{"lang":"python","text":"dpgmm = mixture.BayesianGaussianMixture(\n    n_components=10,\n    covariance_type=\"full\",\n    weight_concentration_prior=1e-2,\n    weight_concentration_prior_type=\"dirichlet_process\",\n    mean_precision_prior=1e-2,\n    covariance_prior=1e0 * np.eye(2),\n    init_params=\"random\",\n    max_iter=100,\n    random_state=2,\n).fit(X)"}]},{"title":"Plot the Results of Bayesian GMM with Low Concentration Prior","body":["Plot the Results of Bayesian GMM with Low Concentration Prior","We will plot the results of the Bayesian Gaussian Mixture Model with a Dirichlet process prior and a low value of the concentration prior."],"code":[{"lang":"python","text":"plot_results(\n    X,\n    dpgmm.predict(X),\n    dpgmm.means_,\n    dpgmm.covariances_,\n    1,\n    \"Bayesian Gaussian mixture models with a Dirichlet process prior \"\n    r\"for $\\gamma_0=0.01$.\",\n)"}]},{"title":"Sample from Bayesian GMM with Low Concentration Prior","body":["Sample from Bayesian GMM with Low Concentration Prior","We will now sample from the Bayesian Gaussian Mixture Model with a Dirichlet process prior and a low value of the concentration prior."],"code":[{"lang":"python","text":"X_s, y_s = dpgmm.sample(n_samples=2000)\nplot_samples(\n    X_s,\n    y_s,\n    dpgmm.n_components,\n    0,\n    \"Gaussian mixture with a Dirichlet process prior \"\n    r\"for $\\gamma_0=0.01$ sampled with $2000$ samples.\",\n)"}]},{"title":"Fit a Bayesian Gaussian Mixture Model with a Dirichlet process prior","body":["Fit a Bayesian Gaussian Mixture Model with a Dirichlet process prior","We will now fit a Bayesian Gaussian Mixture Model with a Dirichlet process prior. We will set a high value of the concentration prior to give the model more liberty to model the fine-grained structure of the data."],"code":[{"lang":"python","text":"dpgmm = mixture.BayesianGaussianMixture(\n    n_components=10,\n    covariance_type=\"full\",\n    weight_concentration_prior=1e2,\n    weight_concentration_prior_type=\"dirichlet_process\",\n    mean_precision_prior=1e-2,\n    covariance_prior=1e0 * np.eye(2),\n    init_params=\"kmeans\",\n    max_iter=100,\n    random_state=2,\n).fit(X)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"X_s, y_s = dpgmm.sample(n_samples=2000)\nplot_samples(\n    X_s,\n    y_s,\n    dpgmm.n_components,\n    1,\n    \"Gaussian mixture with a Dirichlet process prior \"\n    r\"for $\\gamma_0=100$ sampled with $2000$ samples.\",\n)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"}};
